const icon=(name,cls='')=>'<svg class="icon '+cls+'" viewBox="0 0 24 24" aria-hidden="true">'+(paths[name]||paths.box)+'</svg>';
const brand=()=>'<span class="brand"><span class="brand-mark">'+icon('box')+'</span>chantelio<b>BOX</b></span>';
const initials=name=>String(name||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=(name,i=0,cls='')=>'<span class="avatar '+['','blue','pink','purple'][i%4]+' '+cls+'">'+esc(initials(name))+'</span>';
const chip=(text,color='')=>'<span class="chip '+color+'"><i class="dot"></i>'+esc(text)+'</span>';
const btn=(text,action,id='',cls='',ico='')=>'<button type="button" class="btn '+cls+'" data-action="'+action+'"'+(id?' data-id="'+esc(id)+'"':'')+'>'+(ico?icon(ico,'sm'):'')+esc(text)+'</button>';
const link=(text,route,cls='btn',ico='')=>'<a class="'+cls+'" href="#/'+route+'">'+(ico?icon(ico,'sm'):'')+esc(text)+'</a>';
let storage;
try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw new Error('Stockage indisponible');}};}
let state=loadState(storage);
let ui={query:'',filter:'all',unitView:'plan',reservationView:'board',paymentFilter:'all',docFilter:'all',clientFilter:'all',size:'all',portalStep:0,portalLead:null,portalUnit:null,savingFailed:false,estimate:{requests:30,before:20,after:8},tourIndex:0};
let overlay=null,lastFocus=null,toastTimer;
const route=()=>{try{return (location.hash.replace(/^#\/?/,'')||'apercu').split('/').map(decodeURIComponent);}catch{return ['apercu'];}};
const current=()=>centre(state.centre);
const clientOf=l=>state.clients.find(c=>c.id===l.clientId)||{name:'Client',email:'—',phone:'—',type:'Particulier'};
const unitOf=l=>state.units.find(u=>u.id===l.unitId)||{label:'—',area:0,price:0};
const cash=(n,id=state.centre,d=0)=>money(n,id,d);
const leads=()=>activeLeads(state,state.centre);
const badgeFor=l=>{const s=STAGES.find(s=>s.id===stageOf(l));return s?chip(s.label,s.color):chip(l.activated?'Location active':'Archivée',l.activated?'green':'');};
const statusLabel={paid:'Payé',late:'En retard',pending:'À encaisser',partial:'Règlement partiel'};
const statusColor={paid:'green',late:'red',pending:'amber',partial:'blue'};
const heading=(title,sub,actions='',eyebrow='VOTRE CENTRE, L’ESPRIT LIBRE')=>'<header class="page-head"><div><div class="eyebrow">'+esc(eyebrow)+'</div><h1>'+esc(title)+'</h1><p class="sub">'+esc(sub)+'</p></div><div class="row gap8">'+actions+'</div></header>';
const stat=(title,value,detail,ico,em='')=>'<article class="stat-card"><div class="stat-top"><span>'+esc(title)+'</span><span class="stat-icon">'+icon(ico)+'</span></div><div class="stat-value">'+value+'</div><div class="stat-bottom">'+(em?'<em>'+esc(em)+'</em> ':'')+detail+'</div></article>';
const empty=(title,text,action='')=>'<div class="empty">'+icon('inbox')+'<h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+action+'</div>';
const tabs=(items,selected,action)=>'<div class="tabs" role="group" aria-label="Choix de la vue">'+items.map(([id,label,ico])=>'<button type="button" class="tab '+(selected===id?'active':'')+'" data-action="'+action+'" data-id="'+id+'" aria-pressed="'+(selected===id)+'">'+(ico?icon(ico):'')+esc(label)+'</button>').join('')+'</div>';
function persist(){if(!saveState(storage,state)&&!ui.savingFailed){ui.savingFailed=true;toast('Le stockage du navigateur est indisponible. Les changements restent dans cette session.',true);}}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML='<div class="toast '+(error?'error':'')+'">'+icon(error?'info':'check')+'<span>'+esc(message)+'</span></div>';toastTimer=setTimeout(()=>$('#toast-root').replaceChildren(),4500);}
function go(path){location.hash='#/'+path;}
function safeRun(action){try{action();persist();render();renderOverlay();}catch(e){toast(e.message||'Cette action n’a pas pu être effectuée.',true);}}
function footer(){return '<footer class="page-foot"><div class="row">'+icon('shield')+'Démo interactive · données fictives · aucune transaction réelle</div><div class="row">Scénario du 26 octobre 2026 <span>·</span>'+link('À propos de la démo','guide','text-btn')+'</div></footer>';}
const NAV=[['PILOTER',[['apercu','Vue d’ensemble','dashboard'],['reservations','Réservations','inbox'],['box','Mes box','box']]],['GÉRER',[['clients','Clients','users'],['documents','Documents','file'],['contrats','Contrats','pen'],['paiements','Paiements','wallet']]],['ALLER PLUS LOIN',[['automatisations','Automatisations','bolt'],['analyses','Analyses','chart']]]];
const pageNames=Object.fromEntries(NAV.flatMap(x=>x[1]).map(x=>[x[0],x[1]]).concat([['parametres','Paramètres'],['guide','Guide & aide']]));
function shell(content,page){const m=metrics(state,state.centre);return '<div class="mobile-shade" data-action="menu-close"></div><aside class="sidebar"><a href="#/apercu" aria-label="Chantelio Box, accueil">'+brand()+'</a><div class="workspace-tag"><span class="workspace-icon">'+icon('building','sm')+'</span><div><strong>'+esc(state.settings.company)+'</strong><span class="muted">Espace de démonstration</span></div>'+icon('down','sm')+'</div><nav aria-label="Navigation principale">'+NAV.map(([name,items])=>'<div class="nav-label">'+name+'</div>'+items.map(([id,label,ico])=>'<a href="#/'+id+'" class="nav-item '+(page===id?'active':'')+'"'+(page===id?' aria-current="page"':'')+'>'+icon(ico)+'<span>'+label+'</span>'+(id==='reservations'?'<span class="nav-count">'+m.leads+'</span>':id==='paiements'&&m.lateCount?'<span class="nav-count">'+m.lateCount+'</span>':'')+'</a>').join('')).join('')+'</nav><div class="nav-spacer"></div><a class="nav-item '+(page==='parametres'?'active':'')+'" href="#/parametres">'+icon('settings')+'Paramètres</a><a class="nav-item '+(page==='guide'?'active':'')+'" href="#/guide">'+icon('help')+'Guide & aide</a><div class="sidebar-help"><h3>Votre centre en un coup d’œil</h3><p>Découvrez le parcours complet d’une location.</p><button class="text-btn" data-action="tour">Faire le tour '+icon('arrow','sm')+'</button></div><button class="profile" data-action="profile"><span class="avatar sq">IL</span><div class="grow" style="text-align:left"><strong>'+esc(state.settings.contact)+' Lebib</strong><small>Administratrice · démo</small></div>'+icon('down','sm')+'</button></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Ouvrir le menu">'+icon('menu')+'</button><div class="breadcrumb">Mon espace '+icon('chevron','sm')+'<span>'+esc(pageNames[page]||'Vue d’ensemble')+'</span></div><div class="top-actions"><button class="top-search" data-action="search" aria-label="Rechercher un client, un box ou une facture">'+icon('search')+'<span>Rechercher…</span><kbd>⌘ K</kbd></button><label class="sr-only" for="centre-select">Centre de stockage</label><select id="centre-select" class="centre-select" data-change="centre">'+CENTRES.map(c=>'<option value="'+c.id+'" '+(c.id===state.centre?'selected':'')+'>'+c.name+' · '+c.currency+'</option>').join('')+'</select>'+link('Parcours client','client','btn small','external')+'<button class="icon-btn notification-btn" data-action="notifications" aria-label="Voir les notifications">'+icon('bell')+'</button><button data-action="profile" class="avatar" aria-label="Profil de démonstration">IL</button></div></header><main class="main" id="main-content" tabindex="-1">'+content+footer()+'</main></div><nav class="mobile-bottom" aria-label="Accès rapide">'+[['apercu','Accueil','dashboard'],['reservations','Demandes','inbox'],['box','Box','box'],['paiements','Paiements','wallet'],['guide','Aide','help']].map(([r,l,i])=>'<a href="#/'+r+'" class="'+(page===r?'active':'')+'">'+icon(i)+l+'</a>').join('')+'</nav>';}
function revenueChart(){const m=metrics(state,state.centre);const max=Math.ceil(m.monthly*1.15/1000)*1000||1000;const values=[.72,.77,.8,.86,.92,1].map(f=>Math.round(m.monthly*f));const prev=[.62,.65,.71,.77,.82,.89].map(f=>Math.round(m.monthly*f));return '<div class="chart-top"><span class="chart-legend"><i></i>Loyers des box loués</span><span class="chart-legend"><i class="soft"></i>Repère illustratif</span></div><div class="chart-wrap"><div class="chart-scale">'+[1,.75,.5,.25,0].map(x=>'<span>'+Math.round(max*x/1000)+' k</span>').join('')+'</div><div class="chart-bars">'+['Mai','Juin','Juil.','Août','Sept.','Oct.'].map((month,i)=>'<div class="bar-group"><div class="bar-pair"><div class="chart-bar" style="height:'+Math.round(prev[i]/max*100)+'%" data-value="'+esc(cash(prev[i]))+'"></div><div class="chart-bar main-bar '+(i===5?'highlight':'')+'" style="height:'+Math.round(values[i]/max*100)+'%" data-value="'+esc(cash(values[i]))+'"></div></div><span class="bar-label">'+month+'</span></div>').join('')+'</div></div>';}
function occupancyCard(){const m=metrics(state,state.centre),circ=2*Math.PI*65;let offset=0;const segs=[[m.occupied,'#2c6352'],[m.reserved,'#c4d6ad'],[m.free,'#e9eee1'],[m.maintenance,'#d9dfd1']].map(([value,color])=>{const length=value/m.total*circ;const s='<circle cx="84" cy="84" r="65" fill="none" stroke="'+color+'" stroke-width="13" stroke-dasharray="'+Math.max(0,length-3)+' '+circ+'" stroke-dashoffset="'+(-offset)+'"/>';offset+=length;return s;}).join('');return '<article class="card"><div class="card-head"><h2>Occupation du centre</h2>'+icon('box','sm')+'</div><div class="occupancy-body"><div class="donut-wrap"><svg viewBox="0 0 168 168" role="img" aria-label="'+m.occupancy+' % des box commercialisables sont loués">'+segs+'</svg><div class="donut-center"><strong>'+m.occupancy+'<span style="font-size:18px;margin:0">%</span></strong><span>de box loués</span></div></div>'+[['Loués',m.occupied,''],['Réservés',m.reserved,'reserved'],['Disponibles',m.free,'free'],['Maintenance',m.maintenance,'maintenance']].map(([l,v,c])=>'<div class="occupancy-row"><div class="row"><i class="'+c+'"></i>'+l+'</div><strong>'+v+' box</strong></div>').join('')+'</div><div class="card-footer">'+m.total+' box au total · maintenance exclue du taux</div></article>';}
function upcomingTable(ls,limit=5){const list=ls.slice().sort((a,b)=>a.start.localeCompare(b.start)).slice(0,limit);if(!list.length)return empty('Aucune arrivée à préparer','Vos prochaines réservations apparaîtront ici.',btn('Créer une demande','new-reservation','','primary small','plus'));return '<div class="table-scroll"><table class="data-table"><thead><tr><th>Client</th><th>Box</th><th>Arrivée</th><th>Dossier</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>'+list.map((l,i)=>{const c=clientOf(l),u=unitOf(l);return '<tr><td><button class="person" data-action="lead" data-id="'+l.id+'">'+avatar(c.name,i)+'<span><strong>'+esc(c.name)+'</strong><small>'+esc(c.type)+'</small></span></button></td><td><span class="unit-tag">'+icon('box','sm')+esc(u.label)+' · '+u.area+' m²</span></td><td><span style="font-size:11px">'+dateLabel(l.start)+'</span></td><td>'+badgeFor(l)+'</td><td><button class="icon-btn" data-action="lead" data-id="'+l.id+'" aria-label="Ouvrir le dossier de '+esc(c.name)+'">'+icon('chevron','sm')+'</button></td></tr>';}).join('')+'</tbody></table></div>';}
function activityList(limit=4){const events=state.events.filter(e=>e.target?.startsWith(state.centre)||!e.target?.startsWith('ch-')&&!e.target?.startsWith('fr-')).slice(0,limit);return events.length?events.map(e=>'<div class="activity-item"><span class="activity-icon">'+icon({document:'file',payment:'wallet',contract:'pen',new:'inbox',active:'check',archive:'archive',rule:'bolt'}[e.type]||'clock')+'</span><div><p>'+esc(e.text)+'</p><time>'+dateLabel(e.date.slice(0,10))+' · '+new Date(e.date).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Paris'})+'</time></div></div>').join(''):'<p class="muted" style="font-size:11px;padding:20px 0">Les nouvelles actions du centre apparaîtront ici.</p>';}
function overview(){const m=metrics(state,state.centre),ls=leads(),missing=ls.filter(l=>stageOf(l)==='documents'),ready=ls.find(l=>stageOf(l)==='ready');return '<div class="welcome"><div><div class="welcome-date">Lundi 26 octobre 2026 <span style="margin:0 7px;color:#bcc5b3">/</span> '+current().city+'</div><h1>Bonjour '+esc(state.settings.contact)+', <span style="color:#97ac77">tout est à sa place.</span></h1><p>Un regard sur votre centre. Les bonnes actions pour la journée.</p></div><div class="row gap8"><span class="demo-chip"><i class="dot"></i>Démo interactive</span>'+btn('Nouvelle réservation','new-reservation','','primary','plus')+'</div></div><section class="stats" aria-label="Indicateurs du centre">'+stat('Box loués',m.occupied+' <small>/ '+m.sellable+'</small>',m.free+' disponibles à la location','box',m.occupancy+' %')+stat('Loyers mensuels',esc(cash(m.monthly)), 'Sur les locations actives','wallet')+stat('Dossiers en cours',m.leads+' <small>demandes</small>',m.ready+' prêt'+(m.ready>1?'s':'')+' à être confirmé'+(m.ready>1?'s':''),'inbox')+stat('Règlements en retard',esc(cash(m.late)),m.lateCount+' facture'+(m.lateCount>1?'s':'')+' à suivre','clock')+'</section><div class="overview-grid"><div class="primary-column"><article class="card"><div class="card-head"><div><h2>Une vue claire sur vos locations</h2><p>Évolution des loyers mensuels · '+current().currency+'</p></div><span class="chart-month">Mai — Oct. 2026 '+icon('down','sm')+'</span></div><div class="card-body"><div class="chart-summary"><div><strong>'+esc(cash(m.monthly))+'</strong><span>Loyers mensuels des box loués</span></div><span class="chip green">'+m.occupied+' locations actives</span></div>'+revenueChart()+'</div><div class="card-footer">Historique illustratif. Le montant d’octobre est calculé à partir des locations de la démo.</div></article><article class="card"><div class="card-head"><div><h2>Les prochaines arrivées</h2><p>Du premier contact au dossier prêt à louer.</p></div>'+link('Toutes les demandes','reservations','text-btn','arrow')+'</div>'+upcomingTable(ls,4)+'</article><article class="card"><div class="card-head"><div><h2>Un parcours simple, des dossiers complets</h2><p>Chaque étape se met à jour dès qu’une action est réalisée.</p></div>'+btn('Essayer','portal','','small','external')+'</div><div class="card-body"><div class="landing-flow" style="margin:0;padding:20px 18px">'+[['inbox','Demande'],['file','Documents'],['pen','Contrat'],['wallet','Règlement'],['check','Prêt à louer']].map(([i,l],n)=>(n?icon('arrow'):'')+'<div class="flow-step"><span>'+icon(i)+'</span>'+l+'</div>').join('')+'</div></div></article></div><aside class="side-column"><article class="card priority-card"><div class="card-head"><h2 class="priority-title">'+icon('spark')+'À débloquer aujourd’hui</h2><span class="chip outline">'+(missing.length+m.lateCount+(ready?1:0))+'</span></div><div class="card-body">'+(ready?'<div class="priority-item"><span class="priority-icon green">'+icon('check')+'</span><div class="grow"><strong>Une arrivée prête à confirmer</strong><small>'+esc(clientOf(ready).name)+' · box '+esc(unitOf(ready).label)+'</small></div><button class="icon-btn" data-action="lead" data-id="'+ready.id+'" aria-label="Confirmer cette arrivée">'+icon('chevron','sm')+'</button></div>':'')+'<div class="priority-item"><span class="priority-icon">'+icon('file')+'</span><div class="grow"><strong>'+missing.length+' dossier'+(missing.length>1?'s':'')+' à compléter</strong><small>Pièces à recevoir ou à vérifier</small></div><button class="icon-btn" data-action="documents-page" aria-label="Voir les documents à vérifier">'+icon('chevron','sm')+'</button></div><div class="priority-item"><span class="priority-icon">'+icon('wallet')+'</span><div class="grow"><strong>'+esc(cash(m.late))+' à régulariser</strong><small>'+m.lateCount+' règlement'+(m.lateCount>1?'s':'')+' en retard</small></div><button class="icon-btn" data-action="late-page" aria-label="Voir les paiements en retard">'+icon('chevron','sm')+'</button></div></div></article>'+occupancyCard()+'<article class="card activity-card"><div class="card-head"><h2>Le centre en mouvement</h2>'+icon('clock','sm')+'</div><div class="card-body">'+activityList(4)+'</div></article></aside></div><div class="insight-banner">'+icon('spark')+'<div><strong>'+m.free+' box disponibles, des opportunités à suivre.</strong><p>Visualisez les tailles libres et préparez les prochaines locations au bon moment.</p></div>'+link('Voir mes box','box','text-btn','arrow')+'</div>';}
function reservations(){let ls=leads().filter(l=>matches(l));const headingHtml=heading('Chaque demande avance.','De la première prise de contact au box prêt à louer.',btn('Exporter','export-reservations','','','download')+btn('Nouvelle réservation','new-reservation','','primary','plus'));let content='';if(ui.reservationView==='board'){content='<div class="kanban" aria-label="Étapes des réservations">'+STAGES.map(s=>{const col=ls.filter(l=>stageOf(l)===s.id);return '<section class="kanban-column"><h2 class="kanban-heading"><i class="dot" style="color:'+({blue:'#82a1c8',amber:'#caa361',purple:'#b299cd',orange:'#caa080',green:'#89a66c'}[s.color])+'"></i>'+s.short+'<span class="count">'+col.length+'</span></h2>'+col.map((l,i)=>{const c=clientOf(l),u=unitOf(l);return '<button class="kanban-card" data-action="lead" data-id="'+l.id+'"><span class="unit-tag">'+icon('box','sm')+esc(u.label)+' · '+u.area+' m²</span><div class="person">'+avatar(c.name,i)+'<h3>'+esc(c.name)+'</h3></div><div class="kanban-price">'+esc(cash(l.monthly))+' <small>/ mois</small></div><div class="kanban-meta"><span>'+dateLabel(l.start)+'</span><span>'+progressOf(l)+' % complet</span></div><div class="progress-track"><div class="progress-fill" style="width:'+progressOf(l)+'%"></div></div><div class="kanban-next">'+nextAction(l)+icon('arrow')+'</div></button>';}).join('')+(!col.length?'<div class="mini-empty">Tout est à jour ici.<br>Les demandes apparaîtront à cette étape.</div>':'')+'</section>';}).join('')+'</div>';}else content='<article class="card">'+upcomingTable(ls,100)+'</article>';
return headingHtml+'<div class="toolbar">'+tabs([['board','Par étapes','grid'],['list','Liste','list']],ui.reservationView,'reservation-view')+'<div class="search-input">'+icon('search')+'<input id="page-search" data-input="query" type="search" placeholder="Un client, un box…" aria-label="Rechercher dans les réservations" value="'+esc(ui.query)+'"></div></div>'+content+'<div class="inline-info mt20">'+icon('info')+'Un box devient prêt à louer après validation des documents, signature du contrat et réception du premier règlement. L’entrée reste à confirmer par le gérant.</div>';}
function matches(l){const q=ui.query.toLocaleLowerCase('fr');return !q||(clientOf(l).name+' '+clientOf(l).email+' '+unitOf(l).label).toLocaleLowerCase('fr').includes(q);}
function unitsPage(){const m=metrics(state,state.centre);let us=state.units.filter(u=>u.centre===state.centre&&(ui.filter==='all'||u.status===ui.filter)&&(!ui.query||(u.label+' '+u.area+' '+u.building).toLowerCase().includes(ui.query.toLowerCase()))&&(ui.size==='all'||ui.size==='small'&&u.area<=5||ui.size==='medium'&&u.area>5&&u.area<=10||ui.size==='large'&&u.area>10));return heading('Une place pour chaque besoin.','Disponibilités, surfaces et tarifs de votre centre.',btn('Exporter','export-units','','','download')+btn('Ajouter un box','new-unit','','primary','plus'))+'<div class="toolbar"><div class="filters">'+[['all','Tous',m.total],['free','Libres',m.free],['occupied','Loués',m.occupied],['reserved','Réservés',m.reserved],['maintenance','Maintenance',m.maintenance]].map(([id,l,n])=>'<button class="filter '+(ui.filter===id?'active':'')+'" data-action="unit-filter" data-id="'+id+'">'+l+'<span class="count">'+n+'</span></button>').join('')+'</div>'+tabs([['plan','Plan','grid'],['cards','Fiches','box']],ui.unitView,'unit-view')+'</div><div class="toolbar"><div class="unit-legend"><span><i></i>Loué</span><span><i class="reserved"></i>Réservé</span><span><i class="free"></i>Libre</span><span><i class="maintenance"></i>Maintenance</span></div><div class="row gap8"><div class="search-input">'+icon('search')+'<input id="page-search" data-input="query" type="search" placeholder="Rechercher un box…" aria-label="Rechercher un box" value="'+esc(ui.query)+'"></div><label class="sr-only" for="size-filter">Surface des box</label><select id="size-filter" data-change="size" style="font-size:11px"><option value="all" '+(ui.size==='all'?'selected':'')+'>Toutes les surfaces</option><option value="small" '+(ui.size==='small'?'selected':'')+'>Jusqu’à 5 m²</option><option value="medium" '+(ui.size==='medium'?'selected':'')+'>De 6 à 10 m²</option><option value="large" '+(ui.size==='large'?'selected':'')+'>Plus de 10 m²</option></select></div></div>'+(!us.length?'<article class="card">'+empty('Aucun box ne correspond','Essayez une autre recherche ou un autre filtre.',btn('Effacer les filtres','clear-filters','','small'))+'</article>':ui.unitView==='plan'?'<article class="card"><div class="unit-plan">'+[...new Set(us.map(u=>u.building))].map(b=>'<div class="building-head">'+icon('building','sm')+esc(b)+'<small>· '+us.filter(u=>u.building===b).length+' box · schéma de démonstration</small></div><div class="unit-grid">'+us.filter(u=>u.building===b).map(u=>'<button class="unit-box '+u.status+'" data-action="unit" data-id="'+u.id+'" aria-label="Box '+esc(u.label)+', '+u.area+' mètres carrés, '+UNIT_STATUS[u.status]+'">'+icon(u.status==='maintenance'?'settings':'box')+'<strong>'+esc(u.label)+'</strong><span>'+u.area+' m² · '+UNIT_STATUS[u.status]+'</span></button>').join('')+'</div>').join('')+'</div><div class="card-footer">Cliquez sur un box pour voir sa fiche et ses prochaines actions. Le plan représente les états, pas les dimensions réelles du bâtiment.</div></article>':'<div class="unit-cards">'+us.map(u=>'<button class="card unit-card" data-action="unit" data-id="'+u.id+'"><div class="unit-illustration">'+icon('box')+'</div><div class="row between"><h3>Box '+esc(u.label)+'</h3>'+chip(UNIT_STATUS[u.status],u.status==='free'?'green':u.status==='reserved'?'amber':'')+'</div><p>'+u.area+' m² · '+u.volume+' m³ · plain-pied</p><div class="row mt20"><strong>'+esc(cash(u.price))+'</strong><small>/ mois</small></div></button>').join('')+'</div>')+'<div class="inline-info mt20">'+icon('info')+'Les box réservés sont bloqués pour un seul dossier. L’archivage d’une demande remet le box à disposition ; la clôture d’une location conserve les factures.</div>';}

function clientsPage(){let cs=state.clients.filter(c=>c.centre===state.centre).filter(c=>!ui.query||(c.name+' '+c.email).toLowerCase().includes(ui.query.toLowerCase()));const isActive=c=>state.leases.some(l=>l.clientId===c.id&&l.status==='active');if(ui.clientFilter!=='all')cs=cs.filter(c=>ui.clientFilter==='active'?isActive(c):!isActive(c));const limit=ui.clientLimit||20;return heading('Des clients bien accompagnés.','Les coordonnées, les locations et les documents, au même endroit.',btn('Exporter','export-clients','','','download')+btn('Nouvelle réservation','new-reservation','','primary','plus'))+'<div class="toolbar">'+tabs([['all','Tous les clients'],['active','Locataires'],['prospects','Prospects & anciens']],ui.clientFilter,'client-filter')+'<div class="search-input">'+icon('search')+'<input id="page-search" type="search" data-input="query" placeholder="Rechercher un client…" aria-label="Rechercher un client" value="'+esc(ui.query)+'"></div></div><article class="card">'+(cs.length?'<div class="table-scroll"><table class="data-table"><thead><tr><th>Client</th><th>Contact</th><th>Box</th><th>Relation</th><th></th></tr></thead><tbody>'+cs.slice(0,limit).map((c,i)=>{const lease=state.leases.find(l=>l.clientId===c.id&&l.status==='active');const lead=state.leads.find(l=>l.clientId===c.id&&!l.activated&&!l.cancelled);const u=lease?unitOf(lease):lead?unitOf(lead):null;return '<tr><td><button class="person" data-action="client" data-id="'+c.id+'">'+avatar(c.name,i)+'<span><strong>'+esc(c.name)+'</strong><small>'+esc(c.type)+'</small></span></button></td><td style="font-size:11px">'+esc(c.email)+'</td><td>'+(u?'<span class="unit-tag">'+icon('box','sm')+esc(u.label)+'</span>':'—')+'</td><td>'+chip(lease?'Locataire':lead?'Prospect':'Ancien client',lease?'green':lead?'blue':'')+'</td><td><button class="icon-btn" data-action="client" data-id="'+c.id+'" aria-label="Ouvrir la fiche de '+esc(c.name)+'">'+icon('chevron','sm')+'</button></td></tr>';}).join('')+'</tbody></table></div>':empty('Aucun client trouvé','Essayez un autre nom ou une autre adresse email.'))+'<div class="card-footer row between"><span>'+Math.min(limit,cs.length)+' sur '+cs.length+' clients · coordonnées fictives</span>'+(limit<cs.length?btn('Afficher la suite','more-clients','','small'):'')+'</div></article>';}
function documentRecords(){const records=[];for(const r of [...state.leads.filter(l=>l.centre===state.centre&&!l.cancelled&&!l.activated),...state.leases.filter(l=>l.centre===state.centre&&l.status==='active')])for(const [key,status] of Object.entries(r.docs)){records.push({record:r,key,status,name:DOC_LABELS[key],client:clientOf(r),lead:state.leads.includes(r)});}return records;}
function documentsPage(){let docs=documentRecords();const counts={all:docs.length,missing:docs.filter(d=>d.status==='missing').length,received:docs.filter(d=>d.status==='received').length,verified:docs.filter(d=>d.status==='verified').length};docs=docs.filter(d=>(ui.docFilter==='all'||d.status===ui.docFilter)&&(!ui.query||(d.client.name+' '+d.name).toLowerCase().includes(ui.query.toLowerCase())));const limit=ui.docLimit||16;return heading('Un dossier complet, sans les allers-retours.','Repérez les pièces manquantes et vérifiez ce qui vient d’arriver.',btn('Voir les demandes','reservations-page','','','inbox'))+'<div class="toolbar"><div class="filters">'+[['all','Tous'],['missing','À recevoir'],['received','À vérifier'],['verified','Vérifiés']].map(([k,l])=>'<button class="filter '+(ui.docFilter===k?'active':'')+'" data-action="doc-filter" data-id="'+k+'">'+l+'<span class="count">'+counts[k]+'</span></button>').join('')+'</div><div class="search-input">'+icon('search')+'<input id="page-search" type="search" data-input="query" placeholder="Un client, un document…" aria-label="Rechercher un document" value="'+esc(ui.query)+'"></div></div><article class="card"><div class="card-head"><div><h2>Les documents du centre</h2><p>La réception et la vérification sont deux étapes distinctes.</p></div><span class="chip outline">Données fictives</span></div><div class="card-body">'+(docs.length?docs.slice(0,limit).map(d=>'<div class="doc-row"><span class="doc-icon">'+icon('file')+'</span><div class="grow"><strong>'+esc(d.name)+'</strong><small>'+esc(d.client.name)+' · box '+esc(unitOf(d.record).label)+'</small></div><div class="doc-actions">'+chip({missing:'À recevoir',received:'À vérifier',verified:'Vérifié'}[d.status],{missing:'amber',received:'blue',verified:'green'}[d.status])+(d.lead?btn(d.status==='missing'?'Préparer le rappel':d.status==='received'?'Vérifier':'Ouvrir le dossier',d.status==='missing'?'draft':d.status==='received'?'verify-doc':'lead',d.record.id+'|'+(d.status==='received'?d.key:''),'small',d.status==='missing'?'mail':''):btn('Voir la location','client',d.client.id,'small'))+'</div></div>').join(''):empty('Tout est à jour','Aucun document ne correspond à ce filtre.'))+'</div><div class="card-footer row between"><span>'+Math.min(limit,docs.length)+' sur '+docs.length+' documents</span>'+(limit<docs.length?btn('Afficher la suite','more-docs','','small'):'')+'</div></article><div class="inline-info mt20">'+icon('shield')+'Cette démo utilise des documents fictifs. Aucun justificatif réel n’est demandé, envoyé ou conservé.</div>';}
function contractsPage(){let rs=[...leads(),...state.leases.filter(l=>l.centre===state.centre&&l.status==='active')];const pending=leads().filter(l=>l.accepted&&!l.signed).length;rs=rs.filter(r=>(ui.contractFilter!=='tosign'||!r.signed)&&(ui.contractFilter!=='signed'||r.signed)&&(ui.contractFilter!=='active'||r.status==='active')&&matches(r));const limit=ui.contractLimit||15;return heading('Des contrats suivis, de bout en bout.','Préparez le document, suivez la signature et retrouvez la location.',btn('Aperçu du modèle','contract-template','','','eye'))+'<section class="summary-strip"><article class="card"><h3>Signatures à obtenir</h3><div class="stat-value">'+pending+' <small>contrats</small></div><p class="micro">Demandes validées, signature en attente</p></article><article class="card"><h3>Locations actives</h3><div class="stat-value">'+state.leases.filter(l=>l.centre===state.centre&&l.status==='active').length+'</div><p class="micro">Contrats associés à un box loué</p></article><article class="card"><h3>Arrivées prêtes</h3><div class="stat-value">'+metrics(state,state.centre).ready+'</div><p class="micro">Dossier complet et règlement reçu</p></article></section><div class="toolbar">'+tabs([['all','Tous'],['tosign','À signer'],['signed','Signés'],['active','Actifs']],ui.contractFilter||'all','contract-filter')+'<div class="search-input">'+icon('search')+'<input id="page-search" type="search" data-input="query" placeholder="Rechercher un contrat…" aria-label="Rechercher un contrat" value="'+esc(ui.query)+'"></div></div><article class="card">'+(rs.length?'<div class="table-scroll"><table class="data-table"><thead><tr><th>Client</th><th>Box</th><th>Début</th><th>Signature</th><th></th></tr></thead><tbody>'+rs.slice(0,limit).map((r,i)=>'<tr><td><div class="person">'+avatar(clientOf(r).name,i)+'<span><strong>'+esc(clientOf(r).name)+'</strong><small>'+esc(cash(r.monthly))+' / mois</small></span></div></td><td><span class="unit-tag">'+esc(unitOf(r).label)+' · '+unitOf(r).area+' m²</span></td><td style="font-size:11px">'+dateLabel(r.start)+'</td><td>'+chip(r.signed?'Signé'+(r.status==='active'?'':' · simulation'):'À signer',r.signed?'green':'purple')+'</td><td>'+btn('Consulter','contract',r.id,'small','eye')+'</td></tr>').join('')+'</tbody></table></div>':empty('Aucun contrat dans cette vue','Les contrats apparaissent dès la création d’un dossier de location.'))+'<div class="card-footer row between"><span>'+Math.min(limit,rs.length)+' sur '+rs.length+' contrats</span>'+(limit<rs.length?btn('Afficher la suite','more-contracts','','small'):'')+'</div></article><div class="notice mt20">Le document présenté est un exemple de démonstration, sans valeur contractuelle. La signature est simulée. Les modèles définitifs et le prestataire de signature seront choisis avec le centre.</div>';}
function paymentsPage(){const m=metrics(state,state.centre);let invoices=state.invoices.filter(i=>i.centre===state.centre&&(ui.paymentFilter==='all'||ui.paymentFilter==='pending'&&remaining(i)>0||invoiceStatus(i)===ui.paymentFilter)&&matches(i));const limit=ui.paymentLimit||18;const first=leads().filter(l=>l.signed&&!l.paid);return heading('Les paiements, en toute clarté.','Un solde juste, des échéances visibles et un historique conservé.',btn('Exporter les règlements','export-payments','','','download'))+'<section class="summary-strip"><article class="card"><h3>Loyers encaissés · scénario</h3><div class="stat-value">'+esc(cash(m.collected))+'</div><p class="micro">Somme des règlements enregistrés</p></article><article class="card"><h3>Solde à encaisser</h3><div class="stat-value">'+esc(cash(m.outstanding))+'</div><p class="micro">Factures ouvertes, après règlements partiels</p></article><article class="card"><h3>Dont échéances dépassées</h3><div class="stat-value red">'+esc(cash(m.late))+'</div><p class="micro">'+m.lateCount+' factures en retard</p></article></section>'+(first.length?'<div class="inline-info mb20">'+icon('wallet')+'<div class="grow"><strong>'+first.length+' premier'+(first.length>1?'s':'')+' règlement'+(first.length>1?'s':'')+' en attente</strong><br>Le contrat est signé ; le premier loyer et le dépôt restent à recevoir.</div>'+btn('Voir le dossier','lead',first[0].id,'small')+'</div>':'')+'<div class="toolbar">'+tabs([['all','Tous'],['pending','À encaisser'],['late','En retard'],['paid','Payés']],ui.paymentFilter,'payment-filter')+'<div class="search-input">'+icon('search')+'<input id="page-search" type="search" data-input="query" placeholder="Un client, un box…" aria-label="Rechercher un paiement" value="'+esc(ui.query)+'"></div></div><article class="card">'+(invoices.length?'<div class="table-scroll"><table class="data-table"><thead><tr><th>Facture / client</th><th>Échéance</th><th>Montant</th><th>Solde</th><th>État</th><th></th></tr></thead><tbody>'+invoices.slice(0,limit).map(i=>'<tr><td><strong style="font-size:11px">'+esc(i.number)+'</strong><p class="micro" style="margin-top:5px">'+esc(clientOf(i).name)+' · '+esc(unitOf(i).label)+'</p></td><td style="font-size:11px">'+dateLabel(i.due)+'</td><td style="font-size:11px">'+esc(cash(i.amount))+'</td><td style="font-size:11px;font-weight:600">'+esc(cash(remaining(i)))+'</td><td>'+chip(statusLabel[invoiceStatus(i)],statusColor[invoiceStatus(i)])+'</td><td>'+(remaining(i)>0?btn('Enregistrer','payment',i.id,'small','plus'):btn('Reçu','receipt',i.id,'small','download'))+'</td></tr>').join('')+'</tbody></table></div>':empty('Aucune facture dans cette vue','Les filtres vous permettent de retrouver les factures ouvertes et réglées.'))+'<div class="card-footer row between"><span>'+Math.min(limit,invoices.length)+' sur '+invoices.length+' factures · montants de démonstration</span>'+(limit<invoices.length?btn('Afficher la suite','more-payments','','small'):'')+'</div></article><div class="inline-info mt20">'+icon('lock')+'Tous les règlements de cette démo sont simulés. Aucun numéro de carte n’est demandé et aucun argent n’est encaissé. Les dépôts de garantie sont suivis séparément des loyers.</div>';}
function automationsPage(){const total=state.rules.reduce((n,r)=>n+ruleCandidates(state,state.centre,r.id).length,0);return heading('Les bons rappels, au bon moment.','Préparez des relances adaptées à chaque étape du dossier.',btn('Simuler une exécution','run-rules','','primary','play'))+'<div class="split"><section>'+state.rules.map((r,i)=>'<article class="card rule-card"><div class="rule-illustration">'+icon(['file','pen','wallet','clock'][i])+'</div><div class="grow"><div class="row between"><h3>'+esc(r.title)+'</h3><button class="toggle '+(r.enabled?'on':'')+'" role="switch" aria-checked="'+r.enabled+'" data-action="toggle-rule" data-id="'+r.id+'" aria-label="'+esc(r.title)+'"></button></div><p>'+esc(r.description)+'</p><div class="rule-actions">'+btn('Prévisualiser le mail','rule-preview',r.id,'small','eye')+'<span class="micro">'+ruleCandidates(state,state.centre,r.id).length+' dossier'+(ruleCandidates(state,state.centre,r.id).length>1?'s':'')+' concerné'+(ruleCandidates(state,state.centre,r.id).length>1?'s':'')+'</span></div></div></article>').join('')+'</section><aside class="stack"><article class="card"><div class="card-head"><h2>Vous gardez la main.</h2>'+icon('shield','sm')+'</div><div class="card-body"><ul class="checklist"><li>'+icon('check')+'Un message adapté à l’étape réelle du dossier.</li><li>'+icon('check')+'Une prévisualisation avant toute action.</li><li>'+icon('check')+'Un historique visible par le gérant.</li><li>'+icon('check')+'Des règles activables séparément.</li></ul></div></article><article class="card priority-card"><div class="card-head"><h2>Prêt pour un essai ?</h2></div><div class="card-body"><div class="stat-value">'+total+' <small>rappels éligibles</small></div><p class="muted" style="font-size:11px">La simulation enregistre un compte rendu local. Elle n’envoie aucun email et ne programme aucun envoi futur.</p>'+(state.lastRuleRun?'<p class="micro mt12">Dernier essai : '+new Date(state.lastRuleRun).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})+'</p>':'')+'</div></article></aside></div><div class="inline-info mt20">'+icon('info')+'Les délais se calculent sur le scénario du 26 octobre 2026. Un envoi réel nécessitera une connexion à la messagerie et votre validation.</div>';}
function analysesPage(){const m=metrics(state,state.centre),ls=leads();const all=state.leads.filter(l=>l.centre===state.centre&&!l.cancelled);const complete=all.filter(l=>stageOf(l)==='ready'||l.activated).length;const hours=Math.max(0,ui.estimate.requests*(ui.estimate.before-ui.estimate.after)/60);return heading('Comprendre pour mieux piloter.','Les indicateurs utiles, calculés à partir de vos dossiers et de vos box.',btn('Exporter le bilan','export-summary','','','download'))+'<section class="stats">'+stat('Occupation',m.occupancy+'<small>%</small>','Sur '+m.sellable+' box commercialisables','chart')+stat('Revenu mensuel potentiel',esc(cash(m.potential)),'Si tous les box libres sont loués','trend')+stat('Dossiers complets',complete+'<small>/ '+all.length+'</small>','Prêts à louer ou déjà confirmés','file')+stat('Loyers à régulariser',esc(cash(m.late)),m.lateCount+' échéances dépassées','wallet')+'</section><div class="detail-grid"><article class="card"><div class="card-head"><div><h2>Où en sont les demandes ?</h2><p>Une lecture immédiate des étapes à débloquer.</p></div>'+icon('inbox','sm')+'</div><div class="card-body">'+STAGES.map(s=>{const n=ls.filter(l=>stageOf(l)===s.id).length;return '<div class="metric-bar"><span>'+s.short+'</span><div class="progress-track"><div class="progress-fill" style="width:'+(ls.length?n/ls.length*100:0)+'%"></div></div><strong>'+n+'</strong></div>';}).join('')+'<p class="micro mt20">Les demandes archivées et les locations déjà confirmées sont exclues de ce graphique.</p></div></article><article class="card"><div class="card-head"><div><h2>Vos surfaces disponibles</h2><p>Les tailles que vous pouvez proposer maintenant.</p></div>'+icon('box','sm')+'</div><div class="card-body">'+[['Petites · ≤ 5 m²',u=>u.area<=5],['Moyennes · 6–10 m²',u=>u.area>5&&u.area<=10],['Grandes · > 10 m²',u=>u.area>10]].map(([l,f])=>{const n=state.units.filter(u=>u.centre===state.centre&&u.status==='free'&&f(u)).length;return '<div class="metric-bar"><span style="min-width:130px">'+l+'</span><div class="progress-track"><div class="progress-fill" style="width:'+(m.free?n/m.free*100:0)+'%"></div></div><strong>'+n+'</strong></div>';}).join('')+'<p class="micro mt20">Potentiel mensuel calculé aux tarifs affichés, hors remises, charges et délais de relocation.</p></div></article></div><div class="insight-grid mt20"><article class="card insight-card">'+icon('file')+'<h3>'+ls.filter(l=>Object.values(l.docs).includes('received')).length+' dossier(s) à vérifier</h3><p>Un document reçu attend votre validation. Vérifier les pièces peut débloquer la suite du parcours.</p>'+btn('Voir les documents','received-page','','ghost small','arrow')+'</article><article class="card insight-card">'+icon('pen')+'<h3>'+ls.filter(l=>stageOf(l)==='contract').length+' signature(s) en attente</h3><p>Le dossier est vérifié. Le contrat constitue la prochaine étape avant le règlement.</p>'+link('Voir les contrats','contrats','text-btn','arrow')+'</article><article class="card insight-card">'+icon('check')+'<h3>'+m.ready+' arrivée(s) prête(s)</h3><p>Pièces vérifiées, contrat signé et premier règlement reçu. La confirmation vous appartient.</p>'+link('Voir les réservations','reservations','text-btn','arrow')+'</article></div><article class="card mt20"><div class="card-head"><div><h2>Quel temps pourriez-vous libérer ?</h2><p>Une estimation personnalisable, pas une promesse de résultat.</p></div>'+icon('clock','sm')+'</div><div class="card-body"><div class="form-grid"><div class="field"><label for="estimate-requests">Dossiers traités par mois</label><input id="estimate-requests" type="number" min="1" max="5000" data-estimate="requests" value="'+ui.estimate.requests+'"></div><div class="field"><label for="estimate-before">Temps actuel par dossier · minutes</label><input id="estimate-before" type="number" min="0" max="600" data-estimate="before" value="'+ui.estimate.before+'"></div><div class="field"><label for="estimate-after">Temps envisagé avec l’outil · minutes</label><input id="estimate-after" type="number" min="0" max="600" data-estimate="after" value="'+ui.estimate.after+'"></div><div class="field"><span class="field-label">Estimation mensuelle à vos hypothèses</span><div class="stat-value green" id="estimate-result" style="margin:4px 0">'+Math.floor(hours)+' h '+String(Math.round(hours%1*60)).padStart(2,'0')+'</div></div></div><p class="micro mt20">Calcul : dossiers × différence de temps par dossier. Ces valeurs sont des hypothèses de démonstration ; le gain réel doit être mesuré sur le terrain.</p></div></article>';}
function settingsPage(){return heading('Un outil qui suit votre façon de travailler.','Les réglages de votre espace et les particularités du centre.')+'<div class="split"><article class="card"><form data-form="settings"><section class="settings-section"><h2>Votre espace</h2><p>Personnalisez les informations affichées dans la démonstration.</p><div class="form-grid"><div class="field"><label for="company">Nom de votre entreprise</label><input id="company" name="company" required maxlength="70" value="'+esc(state.settings.company)+'"></div><div class="field"><label for="contact-name">Prénom affiché</label><input id="contact-name" name="contact" required maxlength="40" value="'+esc(state.settings.contact)+'"></div></div></section><section class="settings-section"><h2>Centre & devise</h2><p>Chaque centre conserve ses propres montants et ses propres dossiers.</p><div class="form-grid"><div class="field"><label for="settings-centre">Centre sélectionné</label><select id="settings-centre" data-change="centre">'+CENTRES.map(c=>'<option value="'+c.id+'" '+(state.centre===c.id?'selected':'')+'>'+c.name+'</option>').join('')+'</select></div><div class="field"><label for="currency">Devise du centre</label><input id="currency" readonly value="'+current().currency+' · '+current().country+'"><small>Aucune conversion automatique entre les devises.</small></div></div><div class="inline-info mt20">'+icon('info')+'Le dépôt illustratif représente '+current().depositMonths+' mois de loyer pour ce centre fictif. Il s’agit d’un paramètre commercial de scénario, pas d’une règle applicable au pays.</div></section><section class="settings-section"><h2>Préférences de démonstration</h2><div class="setting-row"><div><strong>Notifications dans l’application</strong><p>Afficher les derniers événements du centre.</p></div><button type="button" class="toggle '+(state.settings.notification?'on':'')+'" role="switch" aria-checked="'+state.settings.notification+'" data-action="toggle-notifications" aria-label="Notifications dans l’application"></button></div><div class="row between"><span class="micro">Modifications conservées dans ce navigateur.</span><button class="btn primary" type="submit">'+icon('check','sm')+'Enregistrer</button></div></section></form></article><aside class="stack"><article class="card"><div class="card-head"><h2>Une démo, en confiance.</h2>'+icon('shield','sm')+'</div><div class="card-body"><ul class="checklist"><li>'+icon('check')+'Coordonnées et dossiers fictifs.</li><li>'+icon('check')+'Aucun paiement réel.</li><li>'+icon('check')+'Aucun email envoyé.</li><li>'+icon('check')+'Modifications locales, sans partage entre visiteurs.</li></ul></div></article><article class="card"><div class="card-head"><h2>Repartir à zéro</h2></div><div class="card-body"><p class="muted" style="font-size:11px">Restaurez les dossiers d’exemple pour une nouvelle présentation.</p>'+btn('Réinitialiser la démo','reset-confirm','','danger small mt20','refresh')+'</div></article><article class="card"><div class="card-head"><h2>Présenter le produit</h2></div><div class="card-body"><p class="muted" style="font-size:11px">Une page dédiée pour présenter le fonctionnement et le parcours client.</p>'+link('Découvrir Chantelio Box','presentation','btn small mt20','external')+'</div></article></aside></div>';}
const FAQ=[['Est-ce que cette démonstration envoie des emails ou encaisse de l’argent ?','Non. Les rappels sont des brouillons ou des simulations, les signatures sont fictives et les paiements ne déclenchent aucune transaction. Aucun moyen de paiement réel n’est demandé.'],['Les modifications sont-elles enregistrées ?','Elles sont conservées dans le stockage local de ce navigateur, lorsque celui-ci est disponible. Un autre visiteur verra ses propres données de démonstration. La réinitialisation restaure le scénario de départ.'],['Comment passer de la Suisse à la France ?','Utilisez le sélecteur de centre dans la barre supérieure. Le centre de Lausanne est en CHF et celui d’Annecy en EUR. Les montants sont séparés : ils ne sont ni additionnés entre devises ni convertis.'],['À quoi sert la vérification des documents ?','Le client peut simuler le dépôt d’une pièce. Le gérant la vérifie ensuite. Un dossier reçu n’est donc pas automatiquement considéré comme validé. Cette distinction permet de préparer une entrée avec les bons éléments.'],['Pourquoi le box n’est-il pas automatiquement loué ?','La confirmation appartient au gérant. Les documents doivent être vérifiés, le contrat signé et le premier règlement reçu avant de confirmer l’entrée. Le box réservé est ensuite marqué comme loué.'],['Que reste-t-il à connecter pour une utilisation réelle ?','L’authentification et les comptes des centres, une base de données partagée et sécurisée, le stockage des documents, une messagerie, un prestataire de signature et les moyens de paiement. Les modèles de contrats, la fiscalité et les conditions commerciales devront être adaptés à chaque centre.']];
function faqHtml(){return '<div class="faq">'+FAQ.map(([q,a])=>'<details><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>').join('')+'</div>';}
function guidePage(){return heading('Prenez vos repères.','Une présentation en quelques minutes, du gérant au locataire.',btn('Lancer la visite','tour','','primary','compass'))+'<div class="split"><div class="stack"><article class="card"><div class="card-head"><div><h2>Votre première visite en 5 étapes</h2><p>Un parcours concret pour comprendre le produit.</p></div></div>'+[['Une vue claire sur le centre','Découvrez les box disponibles, les loyers et les priorités du jour.','apercu','Voir le tableau de bord'],['Un dossier client à faire avancer','Ouvrez Emma Laurent, ajoutez une pièce fictive, puis vérifiez les documents.','reservations','Ouvrir les réservations'],['Le point de vue du locataire','Essayez l’ajout de documents, la signature et le règlement simulés.','client','Essayer le parcours client'],['Une arrivée à confirmer','Ouvrez le dossier prêt à louer et confirmez l’entrée. Le box passe en location.','reservations','Confirmer une arrivée'],['Les règlements à suivre','Enregistrez un règlement partiel ou complet et observez le solde se mettre à jour.','paiements','Voir les paiements']].map(([t,d,r,l],i)=>'<div class="guide-step"><span class="step-number">'+(i+1)+'</span><div><h3>'+t+'</h3><p>'+d+'</p>'+link(l,r,'text-btn','arrow')+'</div></div>').join('')+'</article><article class="card"><div class="card-head"><h2>Les réponses aux questions utiles</h2></div><div class="card-body">'+faqHtml()+'</div></article></div><aside class="stack"><article class="card priority-card"><div class="card-head"><h2>Chantelio Box</h2>'+icon('box','sm')+'</div><div class="card-body"><p class="muted" style="font-size:12px">Un projet pour les centres indépendants : faire avancer les locations et repérer ce qui manque, avec une vue simple sur chaque dossier.</p>'+link('Voir la présentation','presentation','btn small mt20','external')+'</div></article><article class="card"><div class="card-head"><h2>Le cadre de la démo</h2></div><div class="card-body"><p class="muted" style="font-size:11px;line-height:1.9">Le scénario est daté du 26 octobre 2026. Les noms, coordonnées, tarifs, box et événements sont fictifs. Cette version permet de tester les interactions ; elle n’est pas destinée à gérer de vrais dossiers clients.</p></div></article></aside></div>';}

function presentation(){return '<div class="landing"><nav class="landing-nav" aria-label="Navigation du produit"><a href="#/presentation">'+brand()+'</a><div class="landing-nav-links"><a href="#fonctionnalites" data-scroll="fonctionnalites">Le quotidien simplifié</a>'+link('Explorer la démo','apercu','btn primary','arrow')+'</div></nav><main id="main-content"><section class="landing-hero"><div><div class="eyebrow">PENSÉ POUR LES CENTRES INDÉPENDANTS</div><h1>Des box bien loués.<br><em>L’esprit plus libre.</em></h1><p>De la demande au premier règlement, faites avancer chaque location avec une vue claire sur ce qui est prêt et ce qui manque.</p><div class="row wrap">'+link('Explorer la démo','apercu','btn primary large','arrow')+link('Côté locataire','client','btn large','external')+'</div><p class="fine">Démo interactive · sans inscription · données entièrement fictives</p></div><div class="hero-product" aria-label="Aperçu du suivi des dossiers"><div class="mini-product"><div class="mini-product-head"><span>'+icon('dashboard','sm')+' Mon centre</span><span class="chip green">Tout est à sa place</span></div><div class="mini-product-body"><div class="eyebrow">LA JOURNÉE COMMENCE BIEN</div><h2 style="font-size:20px;margin-top:9px">Les bonnes actions, maintenant.</h2><div class="mini-stats"><div class="mini-stat"><span>ÉTAPES DU PARCOURS</span><strong>5</strong></div><div class="mini-stat"><span>VUE SUR CHAQUE DOSSIER</span><strong>360°</strong></div></div>'+[['Emma Laurent','Pièce reçue, à vérifier','À vérifier','blue'],['Thomas Perrin','Dossier complet, contrat prêt','À signer','purple'],['Julien Favre','Tous les éléments sont validés','Prêt à louer','green']].map(([n,d,l,c],i)=>'<div class="mini-client">'+avatar(n,i)+'<div class="grow"><strong>'+n+'</strong><p>'+d+'</p></div>'+chip(l,c)+'</div>').join('')+'</div></div><div class="hero-floating">'+icon('check')+'<div><strong>Le dossier est complet.</strong><small>Vous pouvez préparer l’arrivée.</small></div></div></div></section><div class="landing-benefits"><span>'+icon('file')+'Dossiers clients centralisés</span><span>'+icon('pen')+'Contrats suivis</span><span>'+icon('wallet')+'Paiements visibles</span><span>'+icon('home')+'France & Suisse</span></div><section id="fonctionnalites" class="landing-section"><div class="landing-section-head"><div class="eyebrow">MOINS DE RECHERCHE, PLUS DE CLARTÉ</div><h2>Une location ne devrait jamais<br>se perdre entre deux emails.</h2><p>Chaque demande a sa place, sa prochaine action et son historique. Vous savez quoi faire, et votre client sait où il en est.</p></div><div class="landing-feature-grid">'+[['inbox','Le prochain geste, évident.','Une pièce manque, une signature attend, un règlement reste à recevoir : les dossiers sont classés par leur véritable prochaine étape.'],['box','Une disponibilité fiable.','Un box réservé est lié à un dossier unique. Les arrivées et les sorties mettent à jour son état, avec une vue par surface et par bâtiment.'],['users','Un client bien accompagné.','Un parcours simple réunit les pièces, le contrat et le premier règlement. Côté gérant, les éléments reçus restent à vérifier avant l’entrée.'],['wallet','Des montants qui se comprennent.','Retrouvez le montant facturé, ce qui a été payé et le solde restant. Les règlements partiels sont pris en compte sans perdre l’historique.'],['bolt','Des rappels à votre rythme.','Prévisualisez des messages adaptés aux dossiers incomplets, aux signatures et aux règlements. Les règles restent sous votre contrôle.'],['chart','Des décisions mieux éclairées.','Occupation, surfaces libres et dossiers bloqués : suivez des indicateurs utiles, avec des montants séparés en euros et en francs suisses.']].map(([i,t,p])=>'<article class="landing-feature"><div class="feature-icon">'+icon(i)+'</div><h3>'+t+'</h3><p>'+p+'</p></article>').join('')+'</div><div class="landing-flow">'+[['inbox','Une demande'],['file','Un dossier vérifié'],['pen','Un contrat signé'],['wallet','Un règlement reçu'],['check','Une arrivée confirmée']].map(([i,l],n)=>(n?icon('arrow'):'')+'<div class="flow-step"><span>'+icon(i)+'</span>'+l+'</div>').join('')+'</div></section><section class="landing-section" style="padding-top:5px"><div class="landing-section-head"><div class="eyebrow">AVANT D’ALLER PLUS LOIN</div><h2>Les réponses, simplement.</h2></div><div style="max-width:760px;margin:auto">'+faqHtml()+'</div><div class="landing-cta"><h2>Voyez ce que cela change, concrètement.</h2><p>Ouvrez un dossier, préparez une arrivée, essayez le parcours client.</p>'+link('Entrer dans la démonstration','apercu','btn primary large','arrow')+'</div></section></main><footer class="landing-footer">'+brand()+'<p>Projet Chantelio Box · Démonstration interactive<br>Aucun centre réel, aucun témoignage inventé, aucune transaction.</p>'+link('Guide de la démo','guide','text-btn','arrow')+'</footer></div>';}
function portalHeader(){return '<header class="portal-header"><a href="#/presentation">'+brand()+'</a><div class="row gap8"><span class="demo-chip">Parcours client · simulation</span>'+link('Vue gérant','apercu','btn small','external')+'</div></header>';}
function portalSummary(l,u){const c=centre(l?.centre||state.centre),monthly=l?.monthly??u?.price??0,deposit=l?.deposit??monthly*c.depositMonths;return '<aside class="portal-summary"><div class="box-art">'+icon('box')+'</div><h3>'+(u?'Box '+esc(u.label):'Votre espace de stockage')+'</h3><p>'+c.city+(u?' · '+u.area+' m² · '+u.volume+' m³':'')+'</p><div class="divider"></div><div class="price-line"><span>Loyer mensuel</span><strong>'+esc(money(monthly,c.id))+'</strong></div><div class="price-line"><span>Dépôt de garantie</span><strong>'+esc(money(deposit,c.id))+'</strong></div><div class="price-line total"><span>Premier règlement</span><strong>'+esc(money(monthly+deposit,c.id))+'</strong></div><p class="portal-note">Dépôt de garantie distinct du loyer. Montants de démonstration ; conditions définitives à convenir avec le centre.</p><div class="divider"></div><ul class="checklist"><li>'+icon('check')+'Un interlocuteur au centre</li><li>'+icon('check')+'Une étape visible à chaque instant</li><li>'+icon('check')+'Aucun paiement réel dans la démo</li></ul></aside>';}
function bookingPage(){const free=state.units.filter(u=>u.centre===state.centre&&u.status==='free');let selected=free.find(u=>u.id===ui.portalUnit)||free[0];if(selected)ui.portalUnit=selected.id;return '<div class="portal">'+portalHeader()+'<main id="main-content" class="portal-main"><div class="portal-intro"><span class="demo-chip">'+current().country+' · '+current().currency+' · données fictives</span><h1>Un peu d’espace.<br>Beaucoup de simplicité.</h1><p>Choisissez votre box et préparez votre arrivée, à votre rythme.</p></div><div class="portal-layout"><section class="card portal-panel"><div class="row between mb20"><h2>Choisir votre box à '+current().city+'</h2><label><span class="sr-only">Pays et centre du parcours client</span><select data-change="centre" style="font-size:10px">'+CENTRES.map(c=>'<option value="'+c.id+'" '+(c.id===state.centre?'selected':'')+'>'+c.city+' · '+c.currency+'</option>').join('')+'</select></label></div>'+(free.length?'<div class="portal-unit-choice">'+free.map(u=>'<button class="portal-choice '+(selected?.id===u.id?'selected':'')+'" data-action="portal-unit" data-id="'+u.id+'" aria-pressed="'+(selected?.id===u.id)+'">'+(selected?.id===u.id?'<span class="choice-tick">'+icon('check','sm')+'</span>':'')+'<strong>'+u.area+' m²</strong><p>Box '+esc(u.label)+' · '+u.volume+' m³</p><div class="choice-price">'+esc(cash(u.price))+' / mois</div></button>').join('')+'</div><h3 style="margin-bottom:17px">Quelques informations pour préparer le dossier</h3><form data-form="portal-new"><div class="form-grid"><div class="field"><label for="portal-name">Nom complet · exemple fictif</label><input id="portal-name" name="name" required maxlength="100" value="Alex Exemple" autocomplete="off"></div><div class="field"><label for="portal-email">Adresse email · exemple fictif</label><input id="portal-email" name="email" type="email" required value="alex@exemple.invalid" autocomplete="off"></div><div class="field"><label for="portal-start">Date d’entrée souhaitée</label><input id="portal-start" name="start" type="date" required min="'+TODAY+'" value="'+plusDays(TODAY,5)+'"></div><div class="field"><label for="portal-type">Votre besoin</label><select id="portal-type" name="type"><option>Particulier</option><option>Professionnel</option></select></div><div class="field full"><label for="portal-note">Un détail à partager avec le centre ?</label><textarea id="portal-note" name="note" rows="2" maxlength="1000" placeholder="Déménagement, travaux, matériel à stocker…"></textarea></div></div><div class="notice mt20">Utilisez uniquement des informations fictives. Votre essai reste dans ce navigateur et ne réserve aucun box réel.</div><div data-form-error></div><div class="form-actions"><button type="submit" class="btn primary">Préparer mon dossier '+icon('arrow','sm')+'</button></div></form>':empty('Tous les box sont déjà réservés dans ce scénario','Essayez l’autre centre ou réinitialisez la démo depuis les paramètres.'))+'</section>'+portalSummary(null,selected)+'</div><div class="portal-note">Un scénario de démonstration. Aucun contrat réel, aucun justificatif personnel, aucune carte bancaire.</div></main></div>';}
function portalPage(id){let l=state.leads.find(l=>l.id===(id||ui.portalLead)&&!l.cancelled);if(!l)l=activeLeads(state,state.centre).find(x=>!x.activated)||null;if(!l)return '<div class="portal">'+portalHeader()+'<main id="main-content" class="portal-main">'+empty('Votre prochaine location commence ici.','Choisissez un box disponible pour essayer un nouveau parcours.',link('Choisir un box','reserver','btn primary','box'))+'</main></div>';ui.portalLead=l.id;const u=unitOf(l),c=clientOf(l);const step=Math.min(3,Math.max(0,ui.portalStep));const docDone=Object.values(l.docs).every(v=>v!=='missing');const stepLabels=['Vos documents','Votre contrat','Votre règlement','Votre arrivée'];let body='';
  if(step===0){body='<h2>Bonjour '+esc(c.name.split(' ')[0])+', préparons votre arrivée.</h2><p>Ajoutez les pièces demandées. Le centre pourra ensuite vérifier votre dossier.</p><div class="inline-info mb20">'+icon('info')+'Votre espace est réservé dans le scénario. Les pièces ajoutées ci-dessous sont fictives.</div>'+Object.entries(l.docs).map(([k,v])=>'<div class="doc-row"><span class="doc-icon">'+icon('file')+'</span><div class="grow"><strong>'+DOC_LABELS[k]+'</strong><small>'+({missing:'Document à transmettre',received:'Reçu · vérification par le centre à venir',verified:'Vérifié par le centre'}[v])+'</small></div><div class="doc-actions">'+(v==='missing'?'<button class="btn small" data-action="portal-doc" data-id="'+l.id+'|'+k+'">'+icon('upload','sm')+'Ajouter un exemple</button>':chip(v==='verified'?'Vérifié':'Reçu',v==='verified'?'green':'blue'))+'</div></div>').join('')+'<p class="portal-note">Dans cette démo, un clic ajoute un document d’exemple. Aucun fichier personnel n’est nécessaire.</p><div class="form-actions">'+link('Choisir un autre box','reserver','btn ghost')+'<button class="btn primary" data-action="portal-step" data-id="1" '+(!docDone?'disabled':'')+'>Continuer vers le contrat '+icon('arrow','sm')+'</button></div>';}
  else if(step===1){body='<h2>Votre contrat, en un coup d’œil.</h2><p>Vérifiez les informations de la location avant la signature simulée.</p>'+contractHtml(l,true)+(l.signed?'<div class="inline-info mt20">'+icon('check')+'La signature de démonstration est enregistrée.</div><div class="form-actions">'+btn('Retour','portal-step','0','ghost')+btn('Continuer vers le règlement','portal-step','2','primary','arrow')+'</div>':'<form data-form="portal-sign" data-id="'+l.id+'"><div class="field mt20"><label for="signature-name">Votre nom pour la simulation</label><input id="signature-name" name="signature" value="'+esc(c.name)+'" required maxlength="100" autocomplete="off"></div><label class="check-label mt20"><input type="checkbox" name="consent" required><span>Je confirme avoir lu cet exemple et souhaite simuler sa signature. Cette action ne crée aucun engagement réel.</span></label><div data-form-error></div><div class="form-actions">'+btn('Retour','portal-step','0','ghost')+'<button type="submit" class="btn primary">'+icon('pen','sm')+'Simuler la signature</button></div></form>');}
  else if(step===2){body='<h2>Un premier règlement transparent.</h2><p>Le premier mois de loyer et le dépôt sont présentés séparément.</p><div class="price-line"><span>Premier loyer mensuel</span><strong>'+esc(cash(l.monthly,l.centre))+'</strong></div><div class="price-line"><span>Dépôt de garantie</span><strong>'+esc(cash(l.deposit,l.centre))+'</strong></div><div class="price-line total"><span>Total du premier règlement</span><strong>'+esc(cash(l.monthly+l.deposit,l.centre))+'</strong></div><div class="notice mt20">Aucun paiement réel : ne saisissez aucune coordonnée bancaire. Le bouton ci-dessous simule la réception du montant pour vous permettre de voir la suite du parcours.</div>'+(l.paid?'<div class="inline-info mt20">'+icon('check')+'Premier règlement enregistré dans le scénario.</div>':'')+'<div class="form-actions">'+btn('Retour','portal-step','1','ghost')+btn(l.paid?'Voir mon arrivée':'Simuler le règlement',l.paid?'portal-step':'portal-pay',l.paid?'3':l.id,'primary','wallet')+'</div>';}
  else {const verified=Object.values(l.docs).every(v=>v==='verified');body='<div class="portal-success"><div class="success-ring">'+icon('check')+'</div><h2>'+(l.activated?'Votre arrivée est confirmée.':'Votre dossier a bien avancé.')+'</h2><p>'+(l.activated?'Le centre a confirmé votre entrée dans le scénario.':verified?'Le dossier est complet, le contrat est signé et le règlement est reçu. Le centre peut maintenant confirmer votre arrivée.':'Le contrat est signé et le règlement est reçu. Le centre doit encore vérifier vos documents et confirmer votre arrivée.')+'</p><div class="divider"></div><div class="details-list right" style="text-align:left"><div><dt>Votre box</dt><dd>'+esc(u.label)+' · '+u.area+' m²</dd></div><div><dt>Arrivée souhaitée</dt><dd>'+dateLabel(l.start,{day:'numeric',month:'long',year:'numeric'})+'</dd></div><div><dt>Vos documents</dt><dd>'+(verified?'Vérifiés':'À vérifier par le centre')+'</dd></div><div><dt>Votre règlement</dt><dd>'+(l.paid?'Reçu · simulation':'En attente')+'</dd></div></div>'+btn('Voir le dossier côté gérant','portal-manager',l.id,'primary','external')+'<p class="portal-note">Les modalités d’accès sont communiquées par le centre après confirmation. Aucun code d’accès réel n’est généré.</p></div>';}
  return '<div class="portal">'+portalHeader()+'<main id="main-content" class="portal-main"><div class="portal-intro"><span class="demo-chip">'+centre(l.centre).name+' · parcours fictif</span><h1>Votre box, en quelques étapes.</h1><p>Un dossier clair pour préparer votre arrivée sereinement.</p></div><div class="portal-layout"><section class="card portal-panel"><div class="portal-steps">'+stepLabels.map((label,i)=>'<div class="portal-step '+(i<=step?'active':'')+'"><span>'+(i<step?icon('check','sm'):(i+1))+'</span>'+label+'</div>').join('')+'</div>'+body+'</section>'+portalSummary(l,u)+'</div><div class="row between wrap mt20"><p class="portal-note">Un parcours fictif, conservé dans votre navigateur.</p>'+link('Essayer une nouvelle réservation','reserver','text-btn','plus')+'</div></main></div>';}

function render(){const [page,id]=route();const focused=document.activeElement;const focusId=focused?.id;const selection=focused instanceof HTMLInputElement?{start:focused.selectionStart,end:focused.selectionEnd}:null;let html;const pages={apercu:overview,reservations,box:unitsPage,clients:clientsPage,documents:documentsPage,contrats:contractsPage,paiements:paymentsPage,automatisations:automationsPage,analyses:analysesPage,parametres:settingsPage,guide:guidePage};document.body.classList.toggle('public-view',['presentation','client','reserver'].includes(page));
  if(page==='presentation')html=presentation();else if(page==='client')html=portalPage(id);else if(page==='reserver')html=bookingPage();else html=shell((pages[page]||overview)(),pages[page]?page:'apercu');
  $('#app').innerHTML=html;$('#app').inert=!!overlay;document.title=page==='presentation'?'Chantelio Box · Des box bien loués, l’esprit plus libre':page==='client'||page==='reserver'?'Votre box · Chantelio Box':(pageNames[page]||'Vue d’ensemble')+' · Chantelio Box';
  if(focusId){const next=document.getElementById(focusId);if(next){next.focus({preventScroll:true});if(selection&&['text','search','email','tel'].includes(next.type))try{next.setSelectionRange(selection.start,selection.end);}catch{}}}
}

function contractHtml(r,short=false){const u=unitOf(r),c=clientOf(r);return '<article class="contract-paper"><span class="contract-stamp">EXEMPLE FICTIF · SANS VALEUR CONTRACTUELLE</span><h2>Votre location de stockage</h2><p>'+esc(state.settings.company)+' · '+esc(centre(r.centre).city)+'</p><div class="divider"></div><table><tr><td>Client</td><td>'+esc(c.name)+'</td></tr><tr><td>Espace de stockage</td><td>Box '+esc(u.label)+' · '+u.area+' m²</td></tr><tr><td>Arrivée souhaitée</td><td>'+dateLabel(r.start,{day:'numeric',month:'long',year:'numeric'})+'</td></tr><tr><td>Loyer mensuel illustratif</td><td>'+esc(cash(r.monthly,r.centre))+'</td></tr><tr><td>Dépôt de garantie illustratif</td><td>'+esc(cash(r.deposit,r.centre))+'</td></tr></table><h3>Un document pour essayer le parcours</h3><p>Cet exemple permet de visualiser les informations reprises dans un dossier et la place d’une signature dans le parcours client. Il ne constitue ni une offre contractuelle ni un contrat de location.</p>'+(!short?'<h3>Les conditions à définir avec le centre</h3><p>Les modalités d’accès, la durée, la résiliation, les assurances, les biens autorisés, les taxes et le traitement du dépôt devront figurer dans le modèle définitif du centre. Les documents présentés ici ne remplacent pas ce modèle.</p>':'')+'<h3>Signature de démonstration</h3><p>'+(r.signed?'Une signature fictive a été enregistrée dans le scénario.':'La signature de cet exemple n’a pas encore été simulée.')+'</p><p class="micro">Aucun engagement juridique et aucun paiement réel ne découlent de cette démonstration.</p></article>';}
function leadDrawer(id){const l=state.leads.find(l=>l.id===id);if(!l)return empty('Dossier introuvable','Le dossier a peut-être été réinitialisé.');const c=clientOf(l),u=unitOf(l),s=stageOf(l);const task=(title,sub,complete,actionHtml)=>'<div class="task-row"><span class="task-circle '+(complete?'complete':'')+'">'+icon(complete?'check':'clock')+'</span><div class="grow"><strong>'+esc(title)+'</strong><small>'+esc(sub)+'</small></div>'+actionHtml+'</div>';
return '<div class="drawer-stage">'+[l.accepted,l.docs.identity==='verified',l.docs.insurance==='verified',l.signed,l.paid].map(done=>'<span class="'+(done?'done':'')+'"></span>').join('')+'</div><div class="row between">'+badgeFor(l)+'<span class="micro">'+progressOf(l)+' % du dossier complété</span></div><dl class="details-list"><div><dt>Client</dt><dd>'+esc(c.name)+'</dd></div><div><dt>Box réservé</dt><dd>'+esc(u.label)+' · '+u.area+' m²</dd></div><div><dt>Arrivée souhaitée</dt><dd>'+dateLabel(l.start,{day:'numeric',month:'long',year:'numeric'})+'</dd></div><div><dt>Loyer mensuel</dt><dd>'+esc(cash(l.monthly,l.centre))+'</dd></div><div><dt>Email de démonstration</dt><dd>'+esc(c.email)+'</dd></div><div><dt>Origine de la demande</dt><dd>'+esc(l.source)+'</dd></div></dl>'+(l.activated?'<div class="inline-info">'+icon('check')+'La location est confirmée. Le box est maintenant loué.</div>':l.cancelled?'<div class="inline-info">'+icon('archive')+'Cette demande est archivée. Le box a été remis à disposition.</div>':'<section class="drawer-section"><h3>Les étapes à finaliser</h3>'+task('Demande validée',l.accepted?'La proposition est acceptée.':'Vérifiez la demande et le box attribué.',l.accepted,l.accepted?chip('Validée','green'):btn('Valider','accept',id,'small'))+Object.entries(l.docs).map(([k,v])=>task(DOC_LABELS[k],{missing:'Pièce non reçue.',received:'Reçue, en attente de votre vérification.',verified:'Pièce vérifiée.'}[v],v==='verified',v==='verified'?chip('Vérifié','green'):btn(v==='missing'?'Ajouter un exemple':'Vérifier',v==='missing'?'submit-doc':'verify-doc',id+'|'+k,'small',v==='missing'?'upload':'check'))).join('')+task('Contrat signé',l.signed?'Signature fictive enregistrée.':'Prévisualisez le document et essayez la signature.',l.signed,l.signed?chip('Signé','green'):btn('Voir le contrat','contract',id,'small','pen'))+task('Premier règlement',l.paid?'Loyer et dépôt reçus dans le scénario.':'À recevoir : '+cash(l.monthly+l.deposit,l.centre)+' (loyer + dépôt).',l.paid,l.paid?chip('Reçu','green'):'<button class="btn small" data-action="first-payment" data-id="'+id+'" '+(!l.signed?'disabled':'')+'>'+icon('wallet','sm')+'Enregistrer</button>')+'</section>')+(s==='ready'?'<div class="inline-info">'+icon('check')+'Tous les éléments sont validés. Vous pouvez confirmer cette arrivée.</div>':'')+'<section class="drawer-section"><h3>Note sur la demande</h3><form data-form="lead-note" data-id="'+id+'"><div class="field"><label class="sr-only" for="lead-note">Note sur la demande</label><textarea id="lead-note" name="note" rows="3" maxlength="2000" placeholder="Une information utile pour votre équipe…">'+esc(l.note)+'</textarea></div><div class="row" style="justify-content:flex-end;margin-top:10px"><button type="submit" class="btn small">Enregistrer la note</button></div></form></section><section class="drawer-section"><h3>Les derniers événements du dossier</h3>'+state.events.filter(e=>e.target===id).slice(0,5).map(e=>'<div class="activity-item"><span class="activity-icon">'+icon('clock')+'</span><div><p>'+esc(e.text)+'</p><time>'+dateLabel(e.date.slice(0,10))+'</time></div></div>').join('')+(state.events.some(e=>e.target===id)?'':'<p class="micro">Les nouvelles actions apparaîtront ici.</p>')+'</section>';}
function unitDrawer(id){const u=state.units.find(u=>u.id===id);if(!u)return empty('Box introuvable','Choisissez un autre box.');const lease=state.leases.find(l=>l.unitId===id&&l.status==='active');const lead=state.leads.find(l=>l.unitId===id&&!l.cancelled&&!l.activated);return '<div class="row between">'+chip(UNIT_STATUS[u.status],u.status==='free'?'green':u.status==='reserved'?'amber':'')+'<span class="micro">'+esc(u.building)+'</span></div><div class="box-drawer-art">'+icon('box')+'<div><strong>'+u.area+' m²</strong><span>'+u.volume+' m³ · '+esc(u.floor)+'</span></div></div><dl class="details-list"><div><dt>Tarif mensuel affiché</dt><dd>'+esc(cash(u.price,u.centre))+'</dd></div><div><dt>Centre</dt><dd>'+esc(centre(u.centre).name)+'</dd></div><div><dt>Caractéristiques</dt><dd>'+u.features.map(esc).join(' · ')+'</dd></div><div><dt>Dépôt du scénario</dt><dd>'+esc(cash(u.price*centre(u.centre).depositMonths,u.centre))+'</dd></div></dl>'+(lease?'<div class="drawer-section"><h3>Location active</h3><div class="row">'+avatar(clientOf(lease).name,0,'lg')+'<div><h3>'+esc(clientOf(lease).name)+'</h3><p class="micro">Depuis le '+dateLabel(lease.start,{day:'numeric',month:'long',year:'numeric'})+'</p></div></div>'+(lease.end?'<div class="inline-info mt20">'+icon('calendar')+'Sortie prévue le '+dateLabel(lease.end)+'. Le box reste loué jusqu’à la clôture.</div>':'')+'<div class="row wrap mt20">'+btn('Voir le client','client',lease.clientId,'small','users')+btn('Planifier une sortie','plan-exit',lease.id,'small','calendar')+btn('Clôturer la location','end-lease-confirm',lease.id,'small','exit')+'</div></div>':lead?'<div class="inline-info">'+icon('lock')+'Réservé pour '+esc(clientOf(lead).name)+', arrivée le '+dateLabel(lead.start)+'.</div><div class="row mt20">'+btn('Ouvrir le dossier','lead',lead.id,'primary','inbox')+'</div>':u.status==='free'?'<div class="inline-info">'+icon('check')+'Ce box est disponible pour une nouvelle demande.</div><div class="row mt20">'+btn('Créer une réservation','reserve-unit',u.id,'primary','plus')+'</div>':'<div class="notice">Ce box est exclu des disponibilités et du calcul d’occupation commercialisable.</div>')+((u.status==='free'||u.status==='maintenance')?'<div class="row wrap mt20">'+btn('Modifier la fiche','edit-unit',u.id,'small','pen')+btn(u.status==='free'?'Passer en maintenance':'Remettre en disponibilité','unit-status',u.id,'small','settings')+'</div>':'')+'<p class="micro mt20">Les tarifs et dimensions sont fictifs. Les modifications de disponibilité restent dans votre navigateur.</p>';}
function clientDrawer(id){const c=state.clients.find(c=>c.id===id);if(!c)return empty('Client introuvable','Ce scénario a peut-être été réinitialisé.');const leases=state.leases.filter(l=>l.clientId===id);const ls=state.leads.filter(l=>l.clientId===id&&!l.cancelled&&!l.activated);const invoices=state.invoices.filter(i=>i.clientId===id);const balance=invoices.reduce((s,i)=>s+remaining(i),0);return '<div class="row">'+avatar(c.name,0,'lg')+'<div><h2 style="font-size:19px">'+esc(c.name)+'</h2><p class="micro" style="margin-top:6px">'+esc(c.type)+' · '+esc(centre(c.centre).city)+'</p></div></div><dl class="details-list"><div><dt>Email fictif</dt><dd>'+esc(c.email)+'</dd></div><div><dt>Téléphone fictif</dt><dd>'+esc(c.phone||'Non renseigné')+'</dd></div><div><dt>Solde à encaisser</dt><dd>'+esc(cash(balance,c.centre))+'</dd></div><div><dt>Locations actives</dt><dd>'+leases.filter(l=>l.status==='active').length+'</dd></div></dl><section class="drawer-section"><h3>Les locations et les demandes</h3>'+leases.map(l=>'<div class="doc-row"><span class="doc-icon">'+icon('box')+'</span><div class="grow"><strong>Box '+esc(unitOf(l).label)+' · '+unitOf(l).area+' m²</strong><small>'+esc(cash(l.monthly,l.centre))+' / mois · depuis le '+dateLabel(l.start)+'</small></div>'+chip(l.status==='active'?'Location active':'Clôturée',l.status==='active'?'green':'')+btn('Contrat','contract',l.id,'small')+'</div>').join('')+ls.map(l=>'<div class="doc-row"><span class="doc-icon">'+icon('inbox')+'</span><div class="grow"><strong>Box '+esc(unitOf(l).label)+'</strong><small>'+nextAction(l)+'</small></div>'+btn('Ouvrir','lead',l.id,'small')+'</div>').join('')+(!leases.length&&!ls.length?'<p class="micro">Aucune location active pour ce client.</p>':'')+'</section><section class="drawer-section"><h3>Factures récentes</h3>'+invoices.slice(0,4).map(i=>'<div class="doc-row"><span class="doc-icon">'+icon('wallet')+'</span><div class="grow"><strong>'+esc(i.number)+'</strong><small>'+esc(cash(i.amount,i.centre))+' · solde '+esc(cash(remaining(i),i.centre))+'</small></div>'+chip(statusLabel[invoiceStatus(i)],statusColor[invoiceStatus(i)])+'</div>').join('')+(!invoices.length?'<p class="micro">Aucune facture émise dans le scénario.</p>':'')+'</section><section class="drawer-section"><h3>Une note pour l’équipe</h3><form data-form="client-note" data-id="'+id+'"><div class="field"><label class="sr-only" for="client-note">Note interne du client</label><textarea id="client-note" name="note" maxlength="2000" rows="3" placeholder="Une préférence de contact, un point à suivre…">'+esc(c.note)+'</textarea></div><div class="row mt12" style="justify-content:flex-end"><button class="btn small" type="submit">Enregistrer la note</button></div></form></section>';}
function reservationForm(unitId){const us=state.units.filter(u=>u.centre===state.centre&&u.status==='free');return us.length?'<form data-form="reservation"><div class="form-grid"><div class="field"><label for="res-name">Nom du client</label><input id="res-name" name="name" required maxlength="100" placeholder="Ex. Alex Exemple" autocomplete="off"></div><div class="field"><label for="res-email">Email</label><input id="res-email" name="email" type="email" required placeholder="alex@exemple.invalid" autocomplete="off"></div><div class="field full"><label for="res-unit">Box disponible</label><select id="res-unit" name="unitId">'+us.map(u=>'<option value="'+u.id+'" '+(u.id===unitId?'selected':'')+'>Box '+esc(u.label)+' · '+u.area+' m² · '+esc(cash(u.price))+' / mois</option>').join('')+'</select></div><div class="field"><label for="res-start">Date d’entrée souhaitée</label><input id="res-start" name="start" type="date" min="'+TODAY+'" value="'+plusDays(TODAY,3)+'" required></div><div class="field"><label for="res-source">Origine de la demande</label><select id="res-source" name="source"><option>Saisie manuelle</option><option>Téléphone</option><option>Email</option><option>Site internet</option></select></div><div class="field"><label for="res-type">Type de client</label><select id="res-type" name="type"><option>Particulier</option><option>Professionnel</option></select></div><div class="field"><label for="res-phone">Téléphone · facultatif</label><input id="res-phone" name="phone" type="tel" maxlength="50" placeholder="Numéro fictif" autocomplete="off"></div><div class="field full"><label for="res-note">Note sur la demande</label><textarea id="res-note" name="note" rows="3" maxlength="2000" placeholder="Une information utile pour préparer l’arrivée…"></textarea></div></div><div class="notice mt20">Utilisez des informations fictives. Le box sera réservé dans ce scénario après création de la demande.</div><div data-form-error></div><div class="form-actions">'+btn('Annuler','close','','ghost')+'<button type="submit" class="btn primary">'+icon('plus','sm')+'Créer la demande</button></div></form>':empty('Aucun box disponible','Tous les box de ce centre sont loués, réservés ou en maintenance. Vous pouvez essayer l’autre centre.');}
function unitForm(id){const u=state.units.find(u=>u.id===id);return '<form data-form="unit" data-id="'+esc(id||'')+'"><div class="form-grid"><div class="field"><label for="unit-label">Identifiant du box</label><input id="unit-label" name="label" maxlength="20" required value="'+esc(u?.label||'C-01')+'"></div><div class="field"><label for="unit-building">Bâtiment</label><input id="unit-building" name="building" maxlength="40" required value="'+esc(u?.building||'Bâtiment C')+'"></div><div class="field"><label for="unit-area">Surface · m²</label><input id="unit-area" name="area" type="number" min="0.5" max="1000" step="0.1" required value="'+(u?.area||5)+'"></div><div class="field"><label for="unit-price">Loyer mensuel · '+current().currency+'</label><input id="unit-price" name="price" type="number" min="1" max="100000" step="0.01" required value="'+(u?.price||180)+'"></div></div><p class="micro mt20">Le volume est estimé sur une hauteur illustrative de 2,6 m. Le box ajouté sera disponible immédiatement dans le scénario.</p><div data-form-error></div><div class="form-actions">'+btn('Annuler','close','','ghost')+'<button type="submit" class="btn primary">'+icon('check','sm')+'Enregistrer le box</button></div></form>';}
function paymentForm(id){const i=state.invoices.find(i=>i.id===id);if(!i)return empty('Facture introuvable','Choisissez une facture existante.');return '<div class="row mb20">'+avatar(clientOf(i).name)+'<div><h3>'+esc(clientOf(i).name)+'</h3><p class="micro">'+esc(i.number)+' · box '+esc(unitOf(i).label)+'</p></div></div><div class="price-line"><span>Montant de la facture</span><strong>'+esc(cash(i.amount,i.centre,2))+'</strong></div><div class="price-line"><span>Déjà réglé</span><strong>'+esc(cash(i.paid,i.centre,2))+'</strong></div><div class="price-line total"><span>Solde restant</span><strong>'+esc(cash(remaining(i),i.centre,2))+'</strong></div><form data-form="payment" data-id="'+id+'"><div class="form-grid mt20"><div class="field"><label for="payment-amount">Montant reçu · '+centre(i.centre).currency+'</label><input id="payment-amount" name="amount" type="number" min="0.01" step="0.01" max="'+remaining(i)+'" value="'+remaining(i)+'" required></div><div class="field"><label for="payment-method">Mode de règlement illustratif</label><select id="payment-method" name="method"><option>Virement</option><option>Carte · simulation</option><option>Prélèvement · simulation</option></select></div></div><div class="notice mt20">Saisie de démonstration : aucun argent n’est encaissé. Vous pouvez essayer un règlement partiel ; le solde sera recalculé.</div><div data-form-error></div><div class="form-actions">'+btn('Annuler','close','','ghost')+'<button type="submit" class="btn primary">'+icon('check','sm')+'Enregistrer la simulation</button></div></form>';}
function draftText(id,ruleId){const invoice=state.invoices.find(i=>i.id===id),l=state.leads.find(l=>l.id===id);const r=l||invoice;if(!r)return {subject:'Un point sur votre dossier',text:'Bonjour,\n\nNous restons à votre disposition pour préparer votre location.\n\nBonne journée,\nL’équipe '+state.settings.company};const name=clientOf(r).name.split(' ')[0],u=unitOf(r);let subject,body;
  if(invoice){subject='Un point sur votre règlement — box '+u.label;body='Sauf erreur de notre part, il reste un solde de '+cash(remaining(invoice),invoice.centre)+' sur la facture '+invoice.number+', dont l’échéance était le '+dateLabel(invoice.due)+'.\n\nSi le virement vient d’être effectué, merci de nous le préciser pour que nous mettions votre dossier à jour.';}
  else if((ruleId||stageOf(l))==='documents'){const missing=Object.entries(l.docs).filter(([,v])=>v==='missing').map(([k])=>DOC_LABELS[k].toLowerCase());subject='Les dernières pièces pour préparer votre box';body='Pour préparer votre arrivée dans le box '+u.label+', il nous manque '+(missing.length?missing.join(' et '):'la vérification de votre dossier')+'.\n\nVous pouvez retrouver les étapes à compléter dans votre espace client. Nous sommes là si vous avez une question.';}
  else if((ruleId||stageOf(l))==='signature'||stageOf(l)==='contract'){subject='Votre contrat est prêt à être consulté';body='Votre dossier avance bien. Le contrat pour le box '+u.label+' est prêt à être consulté et signé depuis votre espace client.\n\nVous y retrouverez les informations de votre location et le détail des prochaines étapes.';}
  else if((ruleId||stageOf(l))==='payment'){subject='Préparons votre arrivée — premier règlement';body='Votre contrat est signé. Il reste le premier règlement de '+cash(l.monthly+l.deposit,l.centre)+' : '+cash(l.monthly,l.centre)+' de loyer et '+cash(l.deposit,l.centre)+' de dépôt de garantie.\n\nVous retrouverez ce détail dans votre espace client. Le centre pourra ensuite confirmer votre arrivée.';}
  else {subject='Un point sur votre demande de box';body='Nous avons bien votre demande pour le box '+u.label+', avec une arrivée souhaitée le '+dateLabel(l.start)+'.\n\nNous vous accompagnons pour finaliser les documents, le contrat et le premier règlement.';}
  return {subject,text:'Bonjour '+name+',\n\n'+body+'\n\nBonne journée,\nL’équipe '+state.settings.company};}
function draftPreview(id,ruleId){const draft=draftText(id,ruleId);return '<div class="inline-info mb20">'+icon('mail')+'Brouillon de démonstration. Aucun email n’est envoyé.</div><h3 style="margin-bottom:17px">'+esc(draft.subject)+'</h3><div class="email-preview">'+esc(draft.text)+'</div><div class="form-actions">'+btn('Copier le texte','copy-draft',id||'','primary','copy')+btn('Télécharger le brouillon','download-draft',id||'','','download')+'</div>';}
const TOUR=[['Une vue d’ensemble qui aide à agir.','L’accueil rassemble les disponibilités, les montants et les dossiers à débloquer. Les chiffres se mettent à jour quand vous faites avancer une location.','dashboard','apercu'],['Chaque demande a sa prochaine étape.','Dans Réservations, ouvrez un dossier : les documents, la signature et le premier règlement définissent sa progression. Le gérant conserve la décision de confirmer l’entrée.','inbox','reservations'],['Les bonnes pièces, au bon endroit.','Un document transmis reste à vérifier. Essayez le parcours client, puis revenez dans Documents pour constater la mise à jour.','file','documents'],['Des règlements qui se suivent.','Enregistrez un règlement partiel ou complet. Le solde restant et les indicateurs sont recalculés, avec les montants du centre sélectionné.','wallet','paiements'],['Le même dossier, vu par le client.','Le client prépare ses documents, consulte un contrat et simule un règlement. Ses actions apparaissent dans l’espace du gérant sur ce navigateur.','users','client'],['À vous d’essayer.','Commencez avec le dossier de Julien Favre : il est prêt à louer. Confirmez son arrivée et regardez le box passer de réservé à loué.','check','reservations']];
function tourBody(){const [title,text,ico]=TOUR[ui.tourIndex];return '<div class="tour-card"><div class="tour-art">'+icon('box')+icon('arrow')+icon(ico)+icon('arrow')+icon('check')+'</div><div class="eyebrow">ÉTAPE '+(ui.tourIndex+1)+' SUR '+TOUR.length+'</div><h2 style="font-size:22px;margin-top:10px">'+title+'</h2><p>'+text+'</p><div class="tour-dots">'+TOUR.map((_,i)=>'<i class="'+(i===ui.tourIndex?'active':'')+'"></i>').join('')+'</div></div>';}

function openOverlay(kind,id='',extra={}){lastFocus=document.activeElement;overlay={kind,id,...extra};renderOverlay();}
function closeOverlay(){overlay=null;$('#overlay-root').replaceChildren();$('#app').inert=false;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function renderOverlay(){if(!overlay){$('#overlay-root').replaceChildren();$('#app').inert=false;document.body.style.overflow='';return;}const {kind,id}=overlay;let title='',subtitle='',body='',foot='',isDrawer=false,wide=false;const l=state.leads.find(l=>l.id===id);const r=l||state.leases.find(l=>l.id===id);
  if(kind==='lead'){isDrawer=true;title=l?clientOf(l).name:'Dossier client';subtitle=l?'Box '+unitOf(l).label+' · arrivée le '+dateLabel(l.start):'';body=leadDrawer(id);foot=l&&!l.cancelled&&!l.activated?btn('Archiver la demande','cancel-confirm',id,'ghost small','archive')+'<div class="row gap8">'+btn('Vue client','open-portal',id,'small','external')+(stageOf(l)==='ready'?btn('Confirmer l’entrée','activate',id,'primary','check'):btn('Préparer un mail','draft',id,'small','mail'))+'</div>':btn('Fermer','close','','primary');}
  else if(kind==='unit'){isDrawer=true;const u=state.units.find(u=>u.id===id);title=u?'Box '+u.label:'Fiche du box';subtitle='L’espace, sa disponibilité et ses prochaines actions.';body=unitDrawer(id);foot=btn('Fermer','close','','primary');}
  else if(kind==='client'){isDrawer=true;title='Le dossier client';subtitle='Les informations utiles, au même endroit.';body=clientDrawer(id);foot=btn('Fermer','close','','primary');}
  else if(kind==='reservation'){title='Une nouvelle demande';subtitle=current().name+' · '+current().currency;body=reservationForm(id);}
  else if(kind==='unit-form'){title=id?'Modifier le box':'Ajouter un box';subtitle='Une fiche simple, des disponibilités à jour.';body=unitForm(id);}
  else if(kind==='payment'){title='Enregistrer un règlement';subtitle='Simulation · aucun encaissement réel';body=paymentForm(id);}
  else if(kind==='first-payment'){title='Le premier règlement';subtitle=l?clientOf(l).name+' · box '+unitOf(l).label:'';body=l?'<div class="price-line"><span>Premier mois de loyer</span><strong>'+esc(cash(l.monthly,l.centre))+'</strong></div><div class="price-line"><span>Dépôt de garantie</span><strong>'+esc(cash(l.deposit,l.centre))+'</strong></div><div class="price-line total"><span>Total du scénario</span><strong>'+esc(cash(l.monthly+l.deposit,l.centre))+'</strong></div><div class="notice mt20">Cette action simule la réception du règlement. Le dépôt reste distinct des loyers dans les indicateurs. Aucun argent n’est encaissé.</div>':'';foot=btn('Annuler','close','','ghost')+btn('Simuler la réception','confirm-first-payment',id,'primary','check');}
  else if(kind==='contract'){wide=true;title='Le contrat de location';subtitle='Exemple fictif · signature simulée';body=r?contractHtml(r):empty('Contrat introuvable','Choisissez un dossier existant.');foot=btn('Télécharger l’exemple','download-contract',id,'','download')+(l&&!l.signed&&l.accepted?btn('Essayer la signature côté client','sign-portal',id,'primary','pen'):btn('Fermer','close','','primary'));}
  else if(kind==='draft'){title='Un message pour votre client';subtitle='Brouillon à relire · aucun envoi automatique';body=draftPreview(id,overlay.ruleId);}
  else if(kind==='search'){title='Que recherchez-vous ?';subtitle='Clients, box et factures du centre sélectionné.';body='<div class="search-input"><input id="global-search" type="search" placeholder="Un nom, un box ou une facture…" aria-label="Recherche globale" value="'+esc(ui.globalQuery||'')+'" style="width:100%;padding-left:14px"></div><div id="global-results" class="search-results">'+searchResults(ui.globalQuery||'')+'</div>';}
  else if(kind==='notifications'){title='Le centre en mouvement';subtitle='Les événements récents dans votre démonstration.';body=state.settings.notification?activityList(12):'<div class="inline-info">'+icon('bell')+'Les notifications sont désactivées dans les paramètres de cette démo.</div>';foot=btn('Fermer','close','','primary');}
  else if(kind==='profile'){title='Votre espace de démonstration';subtitle=state.settings.contact+' Lebib · administratrice';body='<div class="row mb20">'+avatar('Inès Lebib',0,'lg')+'<div><h3>'+esc(state.settings.company)+'</h3><p class="micro">Aucun compte réel ni connexion nécessaire.</p></div></div><div class="stack">'+link('Personnaliser mon espace','parametres','btn','settings')+link('Présenter Chantelio Box','presentation','btn','external')+link('Comprendre la démonstration','guide','btn','help')+'</div>';}
  else if(kind==='reset'){title='Repartir sur une démo toute neuve ?';subtitle='Les données d’exemple seront restaurées.';body='<p class="muted" style="font-size:12px">Cette action efface uniquement les modifications de cette démonstration dans votre navigateur : demandes ajoutées, règlements simulés, notes et réglages. Aucun dossier réel n’est concerné.</p>';foot=btn('Garder mes essais','close','','ghost')+btn('Restaurer le scénario','reset','','primary','refresh');}
  else if(kind==='cancel'){title='Archiver cette demande ?';subtitle=l?clientOf(l).name+' · box '+unitOf(l).label:'';body='<p class="muted" style="font-size:12px">Le box sera remis à disposition et la demande restera dans les données du scénario avec le statut archivé. Les autres locations sont conservées.</p>';foot=btn('Conserver la demande','close','','ghost')+btn('Archiver la demande','cancel',id,'danger','archive');}
  else if(kind==='end-lease'){const lease=state.leases.find(l=>l.id===id);const outstanding=state.invoices.filter(i=>i.leaseId===id).reduce((s,i)=>s+remaining(i),0);title='Clôturer la location';subtitle=lease?'Box '+unitOf(lease).label+' · '+clientOf(lease).name:'';body='<p class="muted" style="font-size:12px">Le box sera remis à disposition à la date du scénario, le 26 octobre 2026. Le contrat, le client et les factures restent conservés.</p>'+(outstanding?'<div class="notice mt20">Un solde de '+esc(cash(outstanding,lease?.centre))+' reste à encaisser. La clôture n’efface pas cette dette dans le scénario.</div>':'')+'<div class="inline-info mt20">'+icon('info')+'Le dépôt de garantie n’est pas automatiquement remboursé dans cette démonstration.</div>';foot=btn('Annuler','close','','ghost')+btn('Clôturer la location fictive','end-lease',id,'primary','exit');}
  else if(kind==='plan-exit'){const lease=state.leases.find(l=>l.id===id);title='Planifier la sortie';subtitle=lease?'Box '+unitOf(lease).label+' · '+clientOf(lease).name:'';body='<form data-form="plan-exit" data-id="'+id+'"><div class="field"><label for="exit-date">Date de sortie prévue</label><input id="exit-date" name="date" type="date" required min="'+TODAY+'" value="'+(lease?.end||plusDays(TODAY,14))+'"></div><div class="inline-info mt20">'+icon('calendar')+'Le box reste loué jusqu’à la clôture effective par le gérant.</div><div data-form-error></div><div class="form-actions">'+btn('Annuler','close','','ghost')+'<button class="btn primary" type="submit">Enregistrer la date</button></div></form>';}
  else if(kind==='tour'){title='Bienvenue chez Chantelio Box';subtitle='Une première visite, à votre rythme.';body=tourBody();foot=(ui.tourIndex?btn('Précédent','tour-prev','','ghost'):'')+btn('Voir ce module','tour-open','','','external')+btn(ui.tourIndex===TOUR.length-1?'À moi de jouer':'Suivant','tour-next','','primary','arrow');}
  else if(kind==='rule-run'){title='Votre essai est terminé.';subtitle='Simulation locale · aucun email envoyé';body='<div class="success-ring">'+icon('check')+'</div><h2 style="text-align:center;margin-bottom:12px">'+(overlay.count||0)+' rappel'+(overlay.count>1?'s':'')+' identifié'+(overlay.count>1?'s':'')+'</h2><p class="muted" style="font-size:12px;text-align:center">Les règles actives ont été évaluées sur les données du scénario. Un compte rendu a été ajouté à l’historique. Aucun envoi ni tâche future n’a été programmé.</p>';foot=btn('Compris','close','','primary');}
  else {closeOverlay();return;}
  $('#overlay-root').innerHTML='<div class="overlay-backdrop" data-action="close"></div><section class="'+(isDrawer?'drawer':'modal'+(wide?' wide':''))+'" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><header class="'+(isDrawer?'drawer-head':'modal-head')+'"><div><div class="eyebrow">'+(isDrawer?'VOTRE CENTRE, BIEN ORGANISÉ':'CHANTELIO BOX · DÉMONSTRATION')+'</div><h2 id="dialog-title">'+esc(title)+'</h2><p>'+esc(subtitle)+'</p></div><button class="icon-btn" data-action="close" aria-label="Fermer la fenêtre">'+icon('close')+'</button></header><div class="'+(isDrawer?'drawer-body':'modal-body')+'">'+body+'</div>'+(foot?'<footer class="'+(isDrawer?'drawer-footer':'modal-foot')+'">'+foot+'</footer>':'')+'</section>';
  $('#app').inert=true;document.body.style.overflow='hidden';const target=kind==='search'?$('#global-search'):$('#overlay-root [role="dialog"]');target?.focus({preventScroll:true});
}
function searchResults(query){if(!query.trim())return '<div class="mini-empty">Essayez « Emma », « A-01 » ou un numéro de facture.</div>';const q=query.toLowerCase();const items=[...state.clients.filter(c=>c.centre===state.centre&&(c.name+' '+c.email).toLowerCase().includes(q)).slice(0,6).map(c=>({label:c.name,sub:'Client · '+c.type,action:'client',id:c.id,ico:'users'})),...state.units.filter(u=>u.centre===state.centre&&(u.label+' '+u.area+' m²').toLowerCase().includes(q)).slice(0,4).map(u=>({label:'Box '+u.label,sub:u.area+' m² · '+UNIT_STATUS[u.status],action:'unit',id:u.id,ico:'box'})),...state.invoices.filter(i=>i.centre===state.centre&&(i.number+' '+clientOf(i).name).toLowerCase().includes(q)).slice(0,4).map(i=>({label:i.number,sub:clientOf(i).name+' · solde '+cash(remaining(i)),action:remaining(i)>0?'payment':'receipt',id:i.id,ico:'wallet'}))];return items.length?items.map(i=>'<button class="search-result" data-action="'+i.action+'" data-id="'+i.id+'"><span class="doc-icon">'+icon(i.ico)+'</span><span><strong>'+esc(i.label)+'</strong><small>'+esc(i.sub)+'</small></span>'+icon('chevron','sm')+'</button>').join(''):empty('Aucun résultat','Essayez un nom, un identifiant de box ou un numéro de facture différent.');}

function downloadFile(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Le téléchargement est prêt.');}
function documentFile(title,body){return '<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>body{font:15px/1.8 system-ui,sans-serif;color:#294534;max-width:780px;margin:50px auto;padding:25px}h2{font-size:25px}h3{font-size:16px;margin-top:25px}table{width:100%;border-collapse:collapse}td{border-bottom:1px solid #e5eadf;padding:10px 0}td:last-child{text-align:right}.contract-stamp{display:inline-block;background:#fff7df;color:#8b713b;padding:6px 10px;border:1px solid #eadab3;font-size:11px}.micro{font-size:12px;color:#81926e}@media print{body{margin:0;padding:0}}</style><body>'+body+'<hr><p class="micro">Chantelio Box · Démonstration · Document fictif, sans valeur contractuelle.</p></body></html>';}
function exportData(kind){let rows=[],name='export';const c=state.centre;if(kind==='reservations'){name='reservations';rows=[['Client','Box','Surface m²','Arrivée','Étape','Loyer mensuel','Dépôt','Devise'],...leads().map(l=>[clientOf(l).name,unitOf(l).label,unitOf(l).area,l.start,STAGES.find(s=>s.id===stageOf(l))?.label,l.monthly,l.deposit,centre(l.centre).currency])];}else if(kind==='units'){name='box';rows=[['Box','Bâtiment','Surface m²','Volume m³','État','Loyer mensuel','Devise'],...state.units.filter(u=>u.centre===c).map(u=>[u.label,u.building,u.area,u.volume,UNIT_STATUS[u.status],u.price,centre(u.centre).currency])];}else if(kind==='clients'){name='clients';rows=[['Nom','Email fictif','Téléphone fictif','Type','Note'],...state.clients.filter(x=>x.centre===c).map(x=>[x.name,x.email,x.phone,x.type,x.note])];}else if(kind==='payments'){name='paiements';rows=[['Facture','Client','Box','Échéance','Montant','Réglé','Solde','État','Devise'],...state.invoices.filter(i=>i.centre===c).map(i=>[i.number,clientOf(i).name,unitOf(i).label,i.due,i.amount,i.paid,remaining(i),statusLabel[invoiceStatus(i)],centre(i.centre).currency])];}else{const m=metrics(state,c);name='bilan';rows=[['Indicateur','Valeur','Unité'],['Centre',current().name,''],['Scénario',TODAY,''],['Box loués',m.occupied,'box'],['Box libres',m.free,'box'],['Occupation',m.occupancy,'%'],['Loyers mensuels',m.monthly,current().currency],['Loyers encaissés',m.collected,current().currency],['Solde restant',m.outstanding,current().currency],['Dont en retard',m.late,current().currency],['Dossiers en cours',m.leads,'dossiers'],['Prêts à louer',m.ready,'dossiers']];}downloadFile('chantelio-'+name+'-'+current().code.toLowerCase()+'.csv',csv(rows),'text/csv;charset=utf-8');}
function portalGo(id,step=0){closeOverlay();const l=state.leads.find(l=>l.id===id);if(l)state.centre=l.centre;ui.portalLead=id;ui.portalStep=step;persist();go('client/'+encodeURIComponent(id));render();}
function actionHandler(action,rawId=''){const id=rawId.split('|')[0],doc=rawId.split('|')[1];switch(action){
  case 'close':closeOverlay();break;
  case 'menu':document.body.classList.toggle('nav-open');break;
  case 'menu-close':document.body.classList.remove('nav-open');break;
  case 'profile':openOverlay('profile');break;
  case 'search':ui.globalQuery='';openOverlay('search');break;
  case 'notifications':openOverlay('notifications');break;
  case 'lead':openOverlay('lead',id);break;
  case 'client':openOverlay('client',id);break;
  case 'unit':openOverlay('unit',id);break;
  case 'new-reservation':openOverlay('reservation');break;
  case 'reserve-unit':openOverlay('reservation',id);break;
  case 'new-unit':openOverlay('unit-form');break;
  case 'edit-unit':openOverlay('unit-form',id);break;
  case 'contract':openOverlay('contract',id);break;
  case 'contract-template':{const r=leads()[0]||state.leases.find(l=>l.centre===state.centre);if(r)openOverlay('contract',r.id);else toast('Créez d’abord une demande pour illustrer le modèle.');break;}
  case 'payment':openOverlay('payment',id);break;
  case 'first-payment':openOverlay('first-payment',id);break;
  case 'confirm-first-payment':safeRun(()=>{updateLead(state,id,'pay');overlay={kind:'lead',id};toast('Premier règlement reçu dans le scénario.');});break;
  case 'accept':safeRun(()=>{updateLead(state,id,'accept');toast('Demande validée. Le dossier peut avancer.');});break;
  case 'submit-doc':safeRun(()=>{updateLead(state,id,'submitDoc',doc);toast('Document d’exemple reçu, à vérifier.');});break;
  case 'verify-doc':safeRun(()=>{updateLead(state,id,'verifyDoc',doc);if(overlay?.kind!=='lead')overlay={kind:'lead',id};toast('Document vérifié. Le dossier est à jour.');});break;
  case 'activate':safeRun(()=>{activateReservation(state,id);toast('Arrivée confirmée. Le box est maintenant loué.');});break;
  case 'cancel-confirm':openOverlay('cancel',id);break;
  case 'cancel':safeRun(()=>{cancelReservation(state,id);closeOverlay();toast('Demande archivée. Le box est à nouveau disponible.');});break;
  case 'plan-exit':openOverlay('plan-exit',id);break;
  case 'end-lease-confirm':openOverlay('end-lease',id);break;
  case 'end-lease':safeRun(()=>{endLease(state,id);closeOverlay();toast('Location clôturée. Les factures sont conservées.');});break;
  case 'unit-status':safeRun(()=>{const u=state.units.find(u=>u.id===id);if(!u||!['free','maintenance'].includes(u.status))throw new Error('Seul un box libre ou en maintenance peut changer d’état ici.');u.status=u.status==='free'?'maintenance':'free';logEvent(state,'archive','Le box '+u.label+' est maintenant '+UNIT_STATUS[u.status].toLowerCase()+'.',u.id);toast('Disponibilité mise à jour.');});break;
  case 'draft':openOverlay('draft',id);break;
  case 'rule-preview':{const rule=state.rules.find(r=>r.id===id);if(!rule)break;const candidates=ruleCandidates(state,state.centre,id);const selected=candidates[0]?.id||(id==='late'?state.invoices.find(i=>i.centre===state.centre&&remaining(i)>0)?.id:leads()[0]?.id);openOverlay('draft',selected||'',{ruleId:id});break;}
  case 'copy-draft':{const d=draftText(id,overlay?.ruleId);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(d.subject+'\n\n'+d.text).then(()=>toast('Brouillon copié. Aucun email envoyé.')).catch(()=>toast('La copie est indisponible. Utilisez « Télécharger le brouillon ».',true));else toast('Utilisez « Télécharger le brouillon » pour récupérer le texte.');break;}
  case 'download-draft':{const d=draftText(id,overlay?.ruleId);downloadFile('chantelio-brouillon.txt',d.subject+'\n\n'+d.text);break;}
  case 'download-contract':{const r=state.leads.find(l=>l.id===id)||state.leases.find(l=>l.id===id);if(r)downloadFile('chantelio-contrat-exemple-'+unitOf(r).label+'.html',documentFile('Exemple de contrat — Chantelio Box',contractHtml(r)),'text/html;charset=utf-8');break;}
  case 'receipt':{const i=state.invoices.find(i=>i.id===id);if(i)downloadFile('chantelio-recu-exemple-'+i.number+'.html',documentFile('Reçu fictif — '+i.number,'<span class="contract-stamp">REÇU DE DÉMONSTRATION · AUCUN PAIEMENT RÉEL</span><h2>Règlement enregistré</h2><p>'+esc(clientOf(i).name)+'</p><table><tr><td>Facture</td><td>'+esc(i.number)+'</td></tr><tr><td>Montant de la facture</td><td>'+esc(cash(i.amount,i.centre,2))+'</td></tr><tr><td>Règlement enregistré</td><td>'+esc(cash(i.paid,i.centre,2))+'</td></tr><tr><td>Solde restant</td><td>'+esc(cash(remaining(i),i.centre,2))+'</td></tr><tr><td>Mode illustratif</td><td>'+esc(i.method)+'</td></tr></table>'),'text/html;charset=utf-8');break;}
  case 'reservation-view':ui.reservationView=id;render();break;
  case 'unit-view':ui.unitView=id;render();break;
  case 'unit-filter':ui.filter=id;render();break;
  case 'client-filter':ui.clientFilter=id;ui.clientLimit=20;render();break;
  case 'doc-filter':ui.docFilter=id;ui.docLimit=16;render();break;
  case 'payment-filter':ui.paymentFilter=id;ui.paymentLimit=18;render();break;
  case 'contract-filter':ui.contractFilter=id;ui.contractLimit=15;render();break;
  case 'clear-filters':ui.query='';ui.filter='all';ui.size='all';render();break;
  case 'more-clients':ui.clientLimit=(ui.clientLimit||20)+20;render();break;
  case 'more-docs':ui.docLimit=(ui.docLimit||16)+16;render();break;
  case 'more-payments':ui.paymentLimit=(ui.paymentLimit||18)+18;render();break;
  case 'more-contracts':ui.contractLimit=(ui.contractLimit||15)+15;render();break;
  case 'reservations-page':closeOverlay();go('reservations');break;
  case 'documents-page':closeOverlay();go('documents');ui.docFilter='all';render();break;
  case 'received-page':closeOverlay();go('documents');ui.docFilter='received';render();break;
  case 'late-page':closeOverlay();go('paiements');ui.paymentFilter='late';render();break;
  case 'toggle-rule':safeRun(()=>{const r=state.rules.find(r=>r.id===id);if(r)r.enabled=!r.enabled;});break;
  case 'run-rules':safeRun(()=>{const count=state.rules.reduce((sum,r)=>sum+ruleCandidates(state,state.centre,r.id).length,0);state.lastRuleRun=new Date().toISOString();logEvent(state,'rule',count+' rappel(s) identifié(s) par une simulation. Aucun envoi.',state.centre+'-rules');overlay={kind:'rule-run',count};});break;
  case 'toggle-notifications':safeRun(()=>state.settings.notification=!state.settings.notification);break;
  case 'reset-confirm':openOverlay('reset');break;
  case 'reset':state=makeSeed();persist();closeOverlay();go('apercu');render();toast('Le scénario de départ a été restauré.');break;
  case 'tour':ui.tourIndex=0;openOverlay('tour');break;
  case 'tour-prev':ui.tourIndex=Math.max(0,ui.tourIndex-1);renderOverlay();break;
  case 'tour-next':if(ui.tourIndex===TOUR.length-1){closeOverlay();go('reservations');}else{ui.tourIndex++;renderOverlay();}break;
  case 'tour-open':{const page=TOUR[ui.tourIndex][3];closeOverlay();go(page);break;}
  case 'portal':closeOverlay();ui.portalStep=0;go('client');break;
  case 'open-portal':portalGo(id,0);break;
  case 'sign-portal':portalGo(id,1);break;
  case 'portal-unit':ui.portalUnit=id;render();break;
  case 'portal-doc':safeRun(()=>updateLead(state,id,'submitDoc',doc));break;
  case 'portal-step':{const l=state.leads.find(l=>l.id===ui.portalLead);const n=Number(id);if(!l)break;if(n>=1&&Object.values(l.docs).some(v=>v==='missing')){toast('Ajoutez d’abord les deux documents d’exemple.',true);break;}if(n>=1&&!l.accepted){toast('La demande doit d’abord être validée par le centre.',true);break;}if(n>=2&&!l.signed){toast('Simulez d’abord la signature du contrat.',true);break;}if(n>=3&&!l.paid){toast('Simulez d’abord le premier règlement.',true);break;}ui.portalStep=Math.max(0,Math.min(3,n));render();window.scrollTo({top:0,behavior:'instant'});break;}
  case 'portal-pay':safeRun(()=>{updateLead(state,id,'pay');ui.portalStep=3;toast('Règlement simulé. Le centre peut suivre votre dossier.');});window.scrollTo({top:0,behavior:'instant'});break;
  case 'portal-manager':{const l=state.leads.find(l=>l.id===id);if(l)state.centre=l.centre;persist();go('reservations');openOverlay('lead',id);break;}
  default:if(action.startsWith('export-'))exportData(action.slice(7));
}}

document.addEventListener('click',event=>{
  const scrollLink=event.target.closest('[data-scroll]');if(scrollLink){event.preventDefault();document.getElementById(scrollLink.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}
  const target=event.target.closest('[data-action]');if(target){event.preventDefault();if(target.disabled)return;actionHandler(target.dataset.action,target.dataset.id||'');return;}
  const nav=event.target.closest('a[href^="#/"]');if(nav){closeOverlay();document.body.classList.remove('nav-open');if(nav.getAttribute('href')===location.hash){render();window.scrollTo({top:0,behavior:'instant'});}}
});
document.addEventListener('input',event=>{
  const t=event.target;
  if(t.dataset.input==='query'){ui.query=t.value;render();}
  if(t.id==='global-search'){ui.globalQuery=t.value;$('#global-results').innerHTML=searchResults(t.value);}
  if(t.dataset.estimate){const value=Math.min(Number(t.max)||5000,Math.max(0,Number(t.value)||0));ui.estimate[t.dataset.estimate]=value;const hours=Math.max(0,ui.estimate.requests*(ui.estimate.before-ui.estimate.after)/60);const minutes=Math.round(hours*60);$('#estimate-result').textContent=Math.floor(minutes/60)+' h '+String(minutes%60).padStart(2,'0');}
});
document.addEventListener('change',event=>{
  const t=event.target;
  if(t.dataset.change==='centre'&&CENTRES.some(c=>c.id===t.value)){state.centre=t.value;ui.query='';ui.filter='all';ui.size='all';ui.portalUnit=null;ui.portalLead=null;ui.portalStep=0;persist();closeOverlay();if(route()[0]==='client')go('client');render();toast('Centre de '+current().city+' · montants en '+current().currency);}
  if(t.dataset.change==='size'){ui.size=t.value;render();}
});
document.addEventListener('submit',event=>{
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const data=Object.fromEntries(new FormData(form));const kind=form.dataset.form,id=form.dataset.id;const errorBox=form.querySelector('[data-form-error]');if(errorBox)errorBox.innerHTML='';
  try{
    if(kind==='reservation'||kind==='portal-new'){const l=createReservation(state,{...data,centre:state.centre,unitId:kind==='portal-new'?ui.portalUnit:data.unitId,source:kind==='portal-new'?'Parcours client':data.source,accepted:kind==='portal-new'});persist();if(kind==='portal-new'){ui.portalLead=l.id;ui.portalStep=0;go('client/'+l.id);render();}else{overlay={kind:'lead',id:l.id};render();renderOverlay();}toast('Demande créée. Le box est réservé dans le scénario.');}
    else if(kind==='portal-sign'){const l=state.leads.find(l=>l.id===id);if(!l)throw new Error('Dossier introuvable.');if(!data.signature?.trim()||!data.consent)throw new Error('Indiquez un nom et confirmez qu’il s’agit d’une simulation.');if(Object.values(l.docs).some(v=>v==='missing'))throw new Error('Ajoutez d’abord les documents d’exemple.');updateLead(state,id,'sign');ui.portalStep=2;persist();render();toast('Signature simulée. Votre dossier est mis à jour.');window.scrollTo({top:0,behavior:'instant'});}
    else if(kind==='payment'){recordPayment(state,id,data.amount,data.method);persist();closeOverlay();render();toast('Règlement simulé enregistré. Le solde est à jour.');}
    else if(kind==='lead-note'){const l=state.leads.find(l=>l.id===id);if(!l)throw new Error('Dossier introuvable.');l.note=(data.note||'').slice(0,2000);persist();toast('Note de demande enregistrée.');}
    else if(kind==='client-note'){const c=state.clients.find(c=>c.id===id);if(!c)throw new Error('Client introuvable.');c.note=(data.note||'').slice(0,2000);persist();toast('Note du client enregistrée.');}
    else if(kind==='settings'){state.settings.company=data.company.trim().slice(0,70)||'Rivage Stockage';state.settings.contact=data.contact.trim().slice(0,40)||'Inès';persist();render();toast('Préférences enregistrées dans ce navigateur.');}
    else if(kind==='unit'){const label=data.label.trim(),building=data.building.trim(),area=Number(data.area),price=Number(data.price);if(!label||!building||!Number.isFinite(area)||area<.5||area>1000||!Number.isFinite(price)||price<1||price>100000)throw new Error('Vérifiez l’identifiant, la surface et le tarif du box.');if(state.units.some(u=>u.centre===state.centre&&u.label.toLowerCase()===label.toLowerCase()&&u.id!==id))throw new Error('Un box porte déjà cet identifiant dans ce centre.');let u=state.units.find(u=>u.id===id);if(u&&!['free','maintenance'].includes(u.status))throw new Error('Le tarif d’une location en cours ne se modifie pas depuis cette fiche.');if(!u){u={id:uid(state.centre+'-unit'),centre:state.centre,status:'free',floor:'Rez-de-chaussée',features:['Intérieur','Plain-pied','Sec et ventilé']};state.units.push(u);}Object.assign(u,{label:label.slice(0,20),building:building.slice(0,40),area,volume:Math.round(area*2.6),price:Math.round(price*100)/100});logEvent(state,'new','Fiche du box '+u.label+' enregistrée.',u.id);persist();overlay={kind:'unit',id:u.id};render();renderOverlay();toast('Le box est à jour.');}
    else if(kind==='plan-exit'){const lease=state.leases.find(l=>l.id===id);if(!lease||lease.status!=='active')throw new Error('Location introuvable.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date||'')||data.date<TODAY)throw new Error('Choisissez une date à partir du 26 octobre 2026.');lease.end=data.date;logEvent(state,'archive','Sortie du box '+unitOf(lease).label+' prévue le '+dateLabel(data.date)+'.',lease.id);persist();overlay={kind:'unit',id:lease.unitId};render();renderOverlay();toast('Date de sortie prévue enregistrée.');}
  }catch(e){if(errorBox)errorBox.innerHTML='<div class="field-error" role="alert">'+esc(e.message)+'</div>';else toast(e.message||'Vérifiez les informations du formulaire.',true);}
});
document.addEventListener('keydown',event=>{
  if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();ui.globalQuery='';openOverlay('search');}
  if(event.key==='Escape'){closeOverlay();document.body.classList.remove('nav-open');}
  if(event.key==='Tab'&&overlay){const dialog=$('#overlay-root [role="dialog"]');const focusable=[...dialog.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>el.offsetParent!==null);if(!focusable.length){event.preventDefault();dialog.focus();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialog)){event.preventDefault();first.focus();}}
});
window.addEventListener('hashchange',()=>{document.body.classList.remove('nav-open');ui.query='';ui.filter='all';ui.size='all';ui.clientLimit=20;ui.docLimit=16;ui.paymentLimit=18;ui.contractLimit=15;render();if(overlay)renderOverlay();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){state=loadState(storage);render();renderOverlay();}});
render();
